import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
REBALANCE_DAYS = 10
MIN_W, MAX_W = 0.015, 0.16
LAST_DECISION = None


def rank_cross_section(values):
    out = {s: 0.5 for s in UNIVERSE}
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    if len(valid) > 1:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.0) / len(valid)
    return out


def project_weights(raw):
    # Simple deterministic box-constrained normalization for full investment.
    w = {s: max(MIN_W, min(MAX_W, float(raw.get(s, MIN_W)))) for s in UNIVERSE}
    for _ in range(20):
        excess = sum(w.values()) - 1.0
        if abs(excess) < 1e-12:
            break
        if excess > 0:
            free = [s for s in UNIVERSE if w[s] > MIN_W + 1e-12]
            take = excess / max(len(free), 1)
            for s in free:
                w[s] = max(MIN_W, w[s] - take)
        else:
            free = [s for s in UNIVERSE if w[s] < MAX_W - 1e-12]
            add = (-excess) / max(len(free), 1)
            for s in free:
                w[s] = min(MAX_W, w[s] + add)
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


def load_ensemble():
    try:
        data = json.loads(ENSEMBLE_PATH.read_text())
        selected = data.get("selected_factors", [])
        return selected[:10]
    except (OSError, ValueError, TypeError):
        return []


@register_hook
def cross_asset_strategy():
    global LAST_DECISION
    ensemble = load_ensemble()
    if not ensemble:
        return
    # Historical observations stop at the prior completed session in online mode.
    series = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=90)
        if df is None or len(df) < 30:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        close = np.asarray(df["close"], dtype=float)
        high = np.asarray(df["high"], dtype=float)
        low = np.asarray(df["low"], dtype=float)
        ret = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
        series[symbol] = (close, high, low, ret, str(df.iloc[-1]["date"]))
    if len(series) < 12:
        return
    decision = max(v[4] for v in series.values())
    if LAST_DECISION is not None:
        try:
            elapsed = (np.datetime64(decision) - np.datetime64(LAST_DECISION)) / np.timedelta64(1, "D")
            if elapsed < REBALANCE_DAYS:
                return
        except Exception:
            return

    clv, peer, reversal, momentum, invvol = {}, {}, {}, {}, {}
    five_returns = {}
    for s, (c, h, l, r, _) in series.items():
        if len(c) < 22:
            continue
        daily_clv = (2.0 * c - h - l) / np.maximum(h - l, 1e-12)
        vol = max(float(np.std(r[-20:])), 0.008)
        clv[s] = float(np.mean(daily_clv[-3:]))
        five_returns[s] = float(c[-1] / max(c[-6], 1e-12) - 1.0)
        reversal[s] = -five_returns[s] / vol
        momentum[s] = float((c[-1] / max(c[-21], 1e-12) - 1.0) / vol)
        invvol[s] = 1.0 / vol
    for s, value in five_returns.items():
        peers = [v for k, v in five_returns.items() if k != s]
        peer[s] = value - float(np.median(peers)) if peers else 0.0

    ranked = {
        "miner_3_clv_1d": rank_cross_section(clv),
        "peer_median_leadlag_5d": rank_cross_section(peer),
        "short_term_reversal_5d": rank_cross_section(reversal),
        "miner_2_risk_adjusted_momentum_20d": rank_cross_section(momentum),
    }
    score = {s: 0.5 for s in UNIVERSE}
    factor_ids = []
    for item in ensemble:
        fid = str(item.get("factor_id", ""))
        if fid not in ranked:
            continue
        weight = float(item.get("weight", 0.0))
        direction = float(item.get("direction", 1))
        factor_ids.append(fid)
        for s in UNIVERSE:
            score[s] += weight * direction * (ranked[fid].get(s, 0.5) - 0.5)

    # Bullish/moderate SPX keeps broad exposure; a confirmed bearish trend rotates
    # toward tradable defensive benchmarks rather than cash.
    if "SPX" in series:
        spx = series["SPX"][0]
        if spx[-1] < spx[-21] and spx[-1] < spx[-6]:
            for s in ("XAU", "US10Y", "CN10Y"):
                score[s] += 0.16
            for s in ("BTC", "ETH", "WTI"):
                score[s] -= 0.08

    mean_inv = float(np.mean(list(invvol.values()))) if invvol else 1.0
    raw = {s: max(0.02, score[s]) * (0.82 + 0.18 * invvol.get(s, mean_inv) / mean_inv) for s in UNIVERSE}
    weights = project_weights(raw)
    avg = float(np.mean([score[s] for s in UNIVERSE]))
    std = max(float(np.std([score[s] for s in UNIVERSE])), 1e-12)
    forecast_returns = {s: 0.01 * (score[s] - avg) / std for s in UNIVERSE}
    # Complete 15-asset target and deterministic 10-session forecast are required.
    rebalance_to_weights(weights, forecast_returns=forecast_returns,
                         factor_ids=factor_ids[:10], horizon_days=10)
    LAST_DECISION = decision

