import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (register_hook, get_stock_daily_data,
                                    get_index_daily_data, rebalance_to_weights)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
REBALANCE_DAYS = 10
MIN_W, MAX_W = 0.015, 0.16
LAST_DECISION = None


def rank_cs(values):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    if len(good) > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def box_weights(raw):
    w = {s: min(MAX_W, max(MIN_W, float(raw.get(s, MIN_W)))) for s in UNIVERSE}
    for _ in range(30):
        d = sum(w.values()) - 1.0
        if abs(d) < 1e-12:
            break
        free = ([s for s in UNIVERSE if w[s] > MIN_W + 1e-10] if d > 0
                else [s for s in UNIVERSE if w[s] < MAX_W - 1e-10])
        if not free:
            break
        delta = abs(d) / len(free)
        for s in free:
            w[s] = max(MIN_W, w[s] - delta) if d > 0 else min(MAX_W, w[s] + delta)
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


def ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


@register_hook
def cross_asset_strategy():
    global LAST_DECISION
    ens = ensemble()
    if not ens:
        return
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=90)
        if df is None or len(df) < 30:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df.close, dtype=float)
        h = np.asarray(df.high, dtype=float)
        l = np.asarray(df.low, dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1
        data[s] = (c, h, l, r, str(df.iloc[-1].date))
    if len(data) < 12:
        return
    decision = max(x[4] for x in data.values())
    if LAST_DECISION is not None:
        try:
            if (np.datetime64(decision) - np.datetime64(LAST_DECISION)) / np.timedelta64(1, 'D') < REBALANCE_DAYS:
                return
        except Exception:
            return

    clv, lead, rev, mom, vixrev, five, invvol = {}, {}, {}, {}, {}, {}, {}
    for s, (c, h, l, r, _) in data.items():
        vol = max(float(np.std(r[-20:])), 0.008)
        clv[s] = float(np.mean((2*c[-3:] - h[-3:] - l[-3:]) / np.maximum(h[-3:] - l[-3:], 1e-12)))
        five[s] = float(c[-1] / max(c[-6], 1e-12) - 1)
        rev[s] = -five[s] / vol
        mom[s] = float((c[-1] / max(c[-21], 1e-12) - 1) / vol)
        invvol[s] = 1.0 / vol
    for s, x in five.items():
        peers = [v for k, v in five.items() if k != s]
        lead[s] = x - float(np.median(peers)) if peers else 0.0

    # Lagged observation-only VIX shock gate; the asset signal is one-day reversal.
    vdf = get_index_daily_data(symbol="VIX", days=30)
    shock = 0.0
    if vdf is not None and len(vdf) >= 3:
        vc = np.asarray(vdf.sort_values('date').close, dtype=float)
        shock = float(vc[-1] / max(vc[-2], 1e-12) - 1)
    for s, (c, _, _, _, _) in data.items():
        vixrev[s] = -float(c[-1] / max(c[-2], 1e-12) - 1) if shock > 0.03 else 0.0

    ranked = {
        'miner_3_clv_1d': rank_cs(clv),
        'peer_median_leadlag_5d': rank_cs(lead),
        'short_term_reversal_5d': rank_cs(rev),
        'miner_2_risk_adjusted_momentum_20d': rank_cs(mom),
        'miner_3_vix_shock_reversal_1d': rank_cs(vixrev),
    }
    score = {s: 0.5 for s in UNIVERSE}
    ids = []
    for item in ens:
        fid = str(item.get('factor_id', ''))
        if fid not in ranked:
            continue
        ids.append(fid)
        a = float(item.get('weight', 0.0)) * float(item.get('direction', 1))
        for s in UNIVERSE:
            score[s] += a * (ranked[fid].get(s, 0.5) - 0.5)

    # High-risk bearish confirmation tilts to defensive tradable benchmarks.
    if 'SPX' in data and data['SPX'][0][-1] < data['SPX'][0][-21] and data['SPX'][0][-1] < data['SPX'][0][-6]:
        for s in ('XAU', 'US10Y', 'CN10Y'): score[s] += 0.16
        for s in ('BTC', 'ETH', 'WTI'): score[s] -= 0.08
    mean_iv = float(np.mean(list(invvol.values())))
    raw = {s: max(0.02, score[s]) * (0.82 + 0.18 * invvol.get(s, mean_iv) / mean_iv) for s in UNIVERSE}
    weights = box_weights(raw)
    mu, sd = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-12)
    forecast = {s: float(0.01 * (score[s] - mu) / sd) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecast, factor_ids=ids[:10], horizon_days=10)
    LAST_DECISION = decision

