import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
REBALANCE_DAYS = 10
MIN_W, MAX_W = 0.015, 0.16
LAST_DECISION = None


def rank_cs(values):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    if len(good) > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def bounded_weights(raw):
    w = {s: min(MAX_W, max(MIN_W, float(raw.get(s, MIN_W)))) for s in UNIVERSE}
    for _ in range(100):
        gap = sum(w.values()) - 1.0
        if abs(gap) < 1e-12:
            break
        free = [s for s in UNIVERSE if (w[s] > MIN_W + 1e-10 if gap > 0 else w[s] < MAX_W - 1e-10)]
        if not free:
            break
        for s in free:
            w[s] = max(MIN_W, w[s] - gap / len(free)) if gap > 0 else min(MAX_W, w[s] - gap / len(free))
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def macro_returns(symbol, days=110):
    df = get_index_daily_data(symbol=symbol, days=days)
    if df is None or len(df) < 12:
        return None
    c = np.asarray(df.sort_values("date").close, dtype=float)
    return c[1:] / np.maximum(c[:-1], 1e-12) - 1.0


@register_hook
def cross_asset_strategy():
    global LAST_DECISION
    ensemble = load_ensemble()
    if not ensemble:
        return

    data = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=120)
        if df is None or len(df) < 35:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df.close, dtype=float)
        h = np.asarray(df.high, dtype=float)
        lo = np.asarray(df.low, dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        data[symbol] = (c, h, lo, r, str(df.iloc[-1].date))
    if len(data) < 12:
        return

    decision = max(x[4] for x in data.values())
    if LAST_DECISION is not None:
        try:
            if (np.datetime64(decision) - np.datetime64(LAST_DECISION)) / np.timedelta64(1, "D") < REBALANCE_DAYS:
                return
        except Exception:
            return

    clv, peer_input, momentum, consistency, appetite, invvol = {}, {}, {}, {}, {}, {}
    for s, (c, h, lo, r, _) in data.items():
        vol20 = max(float(np.std(r[-20:])), 0.008)
        clv[s] = float(np.mean((2*c[-3:] - h[-3:] - lo[-3:]) / np.maximum(h[-3:] - lo[-3:], 1e-12)))
        peer_input[s] = float(c[-1] / max(c[-6], 1e-12) - 1.0)
        momentum[s] = float((c[-1] / max(c[-21], 1e-12) - 1.0) / vol20)
        consistency[s] = float(np.mean(r[-10:] > 0) * abs(c[-1] / max(c[-11], 1e-12) - 1.0))
        # Factor definition: lagged 10-session realized volatility, higher is appetite.
        lagged10 = r[-11:-1] if len(r) >= 11 else r[:-1]
        appetite[s] = float(np.std(lagged10)) if len(lagged10) >= 8 else np.nan
        invvol[s] = 1.0 / vol20

    leadlag = {}
    for s, value in peer_input.items():
        peers = [v for k, v in peer_input.items() if k != s]
        leadlag[s] = value - float(np.median(peers)) if peers else 0.0

    # Observation-only macro series are gates/signals, never portfolio assets.
    vr = macro_returns("VIX")
    vix_gate = vr is not None and len(vr) >= 65 and vr[-1] > np.percentile(vr[-61:-1], 75)
    dr = macro_returns("DXY")
    dxy_gate = dr is not None and len(dr) >= 65 and abs(dr[-1]) > np.percentile(np.abs(dr[-61:-1]), 75)
    vix_rev, dxy_rev = {}, {}
    for s, (_, _, _, r, _) in data.items():
        vol = max(float(np.std(r[-21:])), 0.008)
        vix_rev[s] = -float(r[-1]) / vol if vix_gate and r[-1] < 0 else 0.0
        dxy_rev[s] = -float(r[-1]) / vol if dxy_gate else 0.0

    ranked = {
        "miner_3_clv_1d": rank_cs(clv),
        "miner_3_vix_downside_extreme_reversal_1d": rank_cs(vix_rev),
        "peer_median_leadlag_5d": rank_cs(leadlag),
        "miner_2_risk_adjusted_momentum_20d": rank_cs(momentum),
        "miner_2_20261203_volatility_appetite": rank_cs(appetite),
        "miner_2_20261119_trend_consistency": rank_cs(consistency),
        "miner_1_dxy_extreme_reversal_1d": rank_cs(dxy_rev),
    }
    score = {s: 0.5 for s in UNIVERSE}
    factor_ids = []
    for item in ensemble:
        fid = str(item.get("factor_id", ""))
        if fid not in ranked:
            continue
        factor_ids.append(fid)
        coefficient = float(item.get("weight", 0.0)) * float(item.get("direction", 1))
        for s in UNIVERSE:
            score[s] += coefficient * (ranked[fid].get(s, 0.5) - 0.5)

    # High-risk sideways/bearish posture: defensive tradable tilts, never cash.
    spx = data.get("SPX")
    if spx and (spx[0][-1] < spx[0][-21] or np.std(spx[3][-20:]) > 0.02):
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.12
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= 0.06

    avg_invvol = float(np.mean(list(invvol.values())))
    raw = {s: max(0.02, score[s]) * (0.80 + 0.20 * invvol.get(s, avg_invvol) / max(avg_invvol, 1e-12)) for s in UNIVERSE}
    weights = bounded_weights(raw)
    mean_score = float(np.mean(list(score.values())))
    sd_score = max(float(np.std(list(score.values()))), 1e-12)
    forecast = {s: float(0.01 * (score[s] - mean_score) / sd_score) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecast, factor_ids=factor_ids[:10], horizon_days=10)
    LAST_DECISION = decision

