import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
MIN_W, MAX_W = 0.02, 0.14
LAST_DECISION = None


def rank_cs(values):
    out = {s: 0.5 for s in UNIVERSE}
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    if len(valid) > 1:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1) / len(valid)
    elif valid:
        out[valid[0][0]] = 0.5
    return out


def bounded(raw):
    w = {s: min(MAX_W, max(MIN_W, float(raw.get(s, MIN_W)))) for s in UNIVERSE}
    for _ in range(50):
        gap = sum(w.values()) - 1.0
        if abs(gap) < 1e-11:
            break
        free = [s for s in UNIVERSE if (w[s] > MIN_W + 1e-10 if gap > 0 else w[s] < MAX_W - 1e-10)]
        if not free:
            break
        for s in free:
            w[s] = max(MIN_W, w[s] - gap / len(free)) if gap > 0 else min(MAX_W, w[s] - gap / len(free))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def macro_returns(symbol):
    try:
        x = get_index_daily_data(symbol=symbol, days=100)
        if x is None or len(x) < 12:
            return None
        c = np.asarray(x.sort_values("date")["close"], float)
        return c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
    except Exception:
        return None


def shock(asset_r, macro_r):
    if macro_r is None or len(macro_r) < 62:
        return 0.0
    threshold = np.percentile(np.abs(macro_r[-61:-1]), 75)
    if abs(macro_r[-1]) <= threshold:
        return 0.0
    return -asset_r[-1] / max(np.std(asset_r[-21:]), 0.008)


@register_hook
def cross_asset_strategy():
    global LAST_DECISION
    ensemble = load_ensemble()
    if not ensemble:
        return
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=150)
        if df is None or len(df) < 65:
            continue
        df = df.sort_values("date")
        c = np.asarray(df["close"], float)
        h = np.asarray(df["high"], float)
        l = np.asarray(df["low"], float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        data[s] = (c, h, l, r, str(df.iloc[-1]["date"]))
    if len(data) < 12:
        return
    decision = max(v[4] for v in data.values())
    if LAST_DECISION is not None and decision == LAST_DECISION:
        return
    LAST_DECISION = decision

    clv, dvol, appetite, trend, shockvol = {}, {}, {}, {}, {}
    for s, (c, h, l, r, _) in data.items():
        vol20 = max(np.std(r[-20:]), 0.008)
        clv[s] = np.mean((2*c[-3:] - h[-3:] - l[-3:]) / np.maximum(h[-3:] - l[-3:], 1e-12))
        # Lagged downside-volatility ratio; missing/short downside samples get neutral rank.
        neg = r[-41:-1][r[-41:-1] < 0]
        dvol[s] = np.std(neg[-10:]) / max(np.std(r[-41:-1]), 0.008) if len(neg) >= 5 else np.nan
        appetite[s] = np.std(r[-11:-1])
        trend[s] = np.mean(r[-11:] > 0) * abs(c[-1] / max(c[-11], 1e-12) - 1)
        shockvol[s] = np.std(r[-6:]) / max(np.std(r[-41:-1]), 0.008)

    vix, dxy = macro_returns("VIX"), macro_returns("DXY")
    copper = data.get("COPPER", (None, None, None, np.array([]), None))[3]
    cn10y = data.get("CN10Y", (None, None, None, np.array([]), None))[3]
    factors = {
        "miner_3_vix_downside_extreme_reversal_1d": {s: (-v[3][-1] / max(np.std(v[3][-21:]), .008) if vix is not None and len(vix) >= 62 and vix[-1] > np.percentile(np.abs(vix[-61:-1]), 75) and v[3][-1] < 0 else 0.) for s, v in data.items()},
        "miner_3_dxy_shock_reversal_1d": {s: shock(v[3], dxy) for s, v in data.items()},
        "miner_2_20270225_downside_vol_ratio": dvol,
        "miner_2_20261203_volatility_appetite": appetite,
        "miner_2_20261119_trend_consistency": trend,
        "miner_1_copper_shock_reversal_1d": {s: shock(v[3], copper) for s, v in data.items()},
        "miner_1_cn10y_shock_reversal_1d": {s: shock(v[3], cn10y) for s, v in data.items()},
        "miner_2_20270128_volatility_shock_ratio": shockvol,
    }
    score = {s: 0.5 for s in UNIVERSE}
    factor_ids = []
    for item in ensemble:
        fid = str(item.get("factor_id", ""))
        factor_ids.append(fid)
        ranked = rank_cs(factors.get(fid, {}))
        q = float(item.get("weight", 0.0)) * float(item.get("direction", 1))
        for s in UNIVERSE:
            score[s] += q * (ranked[s] - 0.5)

    spx = data.get("SPX")
    bear = bool(spx and (spx[0][-1] < spx[0][-21] or np.std(spx[3][-20:]) > .02))
    if bear:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .16
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= .08
    avg_iv = np.mean([1 / max(np.std(v[3][-20:]), .008) for v in data.values()])
    raw = {s: max(.05, score[s]) * (.85 + .15 * (1 / max(np.std(data[s][3][-20:]), .008)) / avg_iv) if s in data else .05 for s in UNIVERSE}
    weights = bounded(raw)
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-12)
    forecasts = {s: float(.01 * (score[s] - mean) / sd) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecasts, factor_ids=factor_ids, horizon_days=10)

