import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def cs_rank(values):
    out = {s: .5 for s in UNIVERSE}
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1) / len(good) if len(good) > 1 else .5
    return out


def shock(asset, macro):
    if macro is None or len(macro) < 62 or len(asset) < 22:
        return 0.0
    limit = np.percentile(np.abs(macro[-61:-1]), 75)
    return -asset[-1] / max(np.std(asset[-21:-1]), .008) if abs(macro[-1]) > limit else 0.0


def normalize(raw):
    # Mild bounds prevent concentration while guaranteeing a complete target.
    w = {s: min(.14, max(.02, float(raw.get(s, .02)))) for s in UNIVERSE}
    for _ in range(30):
        gap = sum(w.values()) - 1.0
        if abs(gap) < 1e-10:
            break
        free = [s for s in UNIVERSE if (.02 < w[s] < .14) or (gap > 0 and w[s] > .02) or (gap < 0 and w[s] < .14)]
        if not free:
            break
        for s in free:
            w[s] = min(.14, max(.02, w[s] - gap / len(free)))
    total = sum(w.values())
    return {s: float(w[s] / total) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if len(ensemble) == 0:
        return
    # Use only completed daily bars returned by the simulator.
    ret, close = {}, {}
    latest_date = None
    for s in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=s, days=150)
            if df is None or len(df) < 65:
                continue
            df = df.sort_values("date")
            c = np.asarray(df["close"], dtype=float)
            ret[s] = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
            close[s] = c
            latest_date = max(latest_date, df.iloc[-1]["date"]) if latest_date is not None else df.iloc[-1]["date"]
        except Exception:
            continue
    if len(ret) < 12 or latest_date is None:
        return
    # Weekday count gives a stable ten-trading-day decision cadence.
    day = latest_date.date() if hasattr(latest_date, "date") else latest_date
    block = int(np.busday_count("2020-01-01", str(day)) // 10)
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    def macro(symbol):
        try:
            df = get_index_daily_data(symbol=symbol, days=100)
            if df is None or len(df) < 62:
                return None
            c = np.asarray(df.sort_values("date")["close"], dtype=float)
            return c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        except Exception:
            return None

    vix, dxy = macro("VIX"), macro("DXY")
    cn10y, us10y = ret.get("CN10Y"), ret.get("US10Y")
    raw_factors = {x["factor_id"]: {} for x in ensemble}
    for s, r in ret.items():
        v20 = max(np.std(r[-21:-1]), .008)
        v60 = max(np.std(r[-61:-1]), .008)
        neg15, neg60 = r[-16:-1][r[-16:-1] < 0], r[-61:-1][r[-61:-1] < 0]
        vals = {
            "miner_2_20270311_downside_vol_ratio_15_60": np.std(neg15) / max(np.std(neg60), .008) if len(neg15) >= 3 and len(neg60) >= 5 else np.nan,
            "miner_3_vix_downside_extreme_reversal_1d": -r[-1] / v20 if vix is not None and vix[-1] > np.percentile(np.abs(vix[-61:-1]), 75) and r[-1] < 0 else 0.0,
            "miner_3_dxy_shock_reversal_1d": shock(r, dxy),
            "miner_2_20261203_volatility_appetite": -v20,
            "miner_2_20270422_vol_adjusted_momentum_20d": np.sum(r[-20:]) / v20,
            "miner_1_relative_momentum_40d": np.sum(r[-40:]) / max(v60, .008),
            "miner_2_20270128_volatility_shock_ratio": v20 / v60,
            "miner_2_20261119_trend_consistency": np.mean(r[-11:] > 0) * np.sum(r[-10:]),
            "miner_3_bear_breadth_reversal_1d": -r[-1] / v20 if r[-1] < 0 else 0.0,
            "miner_3_us10y_shock_reversal_1d": shock(r, us10y),
        }
        for fid in raw_factors:
            raw_factors[fid][s] = vals.get(fid, np.nan)

    score = {s: .5 for s in UNIVERSE}
    factor_ids = []
    for item in ensemble:
        fid = str(item["factor_id"])
        factor_ids.append(fid)
        ranked = cs_rank(raw_factors[fid])
        for s in UNIVERSE:
            score[s] += float(item["weight"]) * int(item.get("direction", 1)) * (ranked[s] - .5)

    spx = ret.get("SPX")
    stressed = spx is not None and (np.sum(spx[-20:]) < 0 or np.std(spx[-20:]) > .02)
    if stressed:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .14
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= .06
    invvol = {s: 1 / max(np.std(ret[s][-20:]), .008) for s in ret}
    mean_inv = np.mean(list(invvol.values()))
    raw = {s: max(.03, score[s]) * (.85 + .15 * invvol.get(s, mean_inv) / mean_inv) for s in UNIVERSE}
    weights = normalize(raw)
    mu, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-9)
    forecasts = {s: float(.01 * (score[s] - mu) / sd) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecasts, factor_ids=factor_ids, horizon_days=10)

