import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def rank_cs(values):
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1) / n if n > 1 else 0.5
    return out


def bounded_weights(raw):
    w = {s: min(0.14, max(0.02, float(raw.get(s, 0.02)))) for s in UNIVERSE}
    for _ in range(50):
        gap = sum(w.values()) - 1.0
        if abs(gap) < 1e-10:
            break
        eligible = [s for s in UNIVERSE if (gap > 0 and w[s] > .0200001) or (gap < 0 and w[s] < .1399999)]
        if not eligible:
            break
        for s in eligible:
            w[s] = min(.14, max(.02, w[s] - gap / len(eligible)))
    total = sum(w.values())
    return {s: float(w[s] / total) for s in UNIVERSE}


def macro_returns(symbol):
    try:
        df = get_index_daily_data(symbol=symbol, days=100)
        if df is None or len(df) < 62:
            return None
        c = np.asarray(df.sort_values("date")["close"], dtype=float)
        return c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
    except Exception:
        return None


def shock_reversal(asset, macro):
    if macro is None or len(macro) < 62:
        return 0.0
    threshold = np.percentile(np.abs(macro[-61:-1]), 75)
    return -asset[-1] / max(np.std(asset[-21:-1]), .008) if abs(macro[-1]) > threshold else 0.0


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble:
        return
    ret = {}
    latest_date = None
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=150)
            if df is None or len(df) < 65:
                continue
            df = df.sort_values("date")
            c = np.asarray(df["close"], dtype=float)
            ret[symbol] = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
