        except Exception:
            pass
    if len(ret) < 12 or latest_date is None:
        return
    day = latest_date.date() if hasattr(latest_date, "date") else latest_date
    block = int(np.busday_count("2020-01-01", str(day)) // 10)
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    vix, dxy = macro_returns("VIX"), macro_returns("DXY")
