            "miner_3_vix_downside_extreme_reversal_1d": -r[-1] / v20 if vix is not None and vix[-1] > np.percentile(np.abs(vix[-61:-1]), 75) and r[-1] < 0 else 0.0,
            "miner_3_bear_breadth_reversal_1d": -r[-1] / v20 if r[-1] < 0 else 0.0,
            "miner_3_trend_consistency_60d": np.mean(r[-60:] > 0) * np.sum(r[-60:]),
            "miner_2_20261203_volatility_appetite": -v20,
            "miner_3_dxy_shock_reversal_1d": shock_reversal(r, dxy),
            "miner_2_20270422_vol_adjusted_momentum_20d": np.sum(r[-20:]) / v20,
            "miner_2_20270128_volatility_shock_ratio": v20 / v60,
            "miner_3_us10y_shock_reversal_1d": shock_reversal(r, us10y),
