import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def rank_cs(values):
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if len(good) == 1:
        out[good[0][0]] = 0.5
    elif good:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1) / len(good)
    return out


def bounded_weights(raw):
    # Mild floors and caps preserve diversification in this deliberately small universe.
    w = {s: min(0.14, max(0.02, float(raw.get(s, 0.02)))) for s in UNIVERSE}
    for _ in range(100):
        gap = sum(w.values()) - 1.0
        if abs(gap) < 1e-10:
            break
        eligible = [s for s in UNIVERSE if (gap > 0 and w[s] > .020001) or (gap < 0 and w[s] < .139999)]
        if not eligible:
            break
        for s in eligible:
            w[s] = min(.14, max(.02, w[s] - gap / len(eligible)))
    total = sum(w.values())
    return {s: float(w[s] / total) for s in UNIVERSE}


def macro_returns(symbol):
    try:
        df = get_index_daily_data(symbol=symbol, days=100)
        if df is None or len(df) < 62:
            return None
        c = np.asarray(df.sort_values("date")["close"], dtype=float)
        return c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
    except Exception:
        return None


def shock_reversal(asset_returns, macro):
    if macro is None or len(macro) < 62:
        return 0.0
    threshold = np.percentile(np.abs(macro[-61:-1]), 75)
    if abs(macro[-1]) > threshold:
        return -asset_returns[-1] / max(np.std(asset_returns[-21:-1]), .008)
    return 0.0


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if len(ensemble) == 0:
        return

    returns, latest_date = {}, None
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=150)
            if df is None or len(df) < 65:
                continue
            df = df.sort_values("date")
            close = np.asarray(df["close"], dtype=float)
            returns[symbol] = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
            d = df.iloc[-1]["date"]
            latest_date = d if latest_date is None else max(latest_date, d)
        except Exception:
            continue
    if len(returns) < 12 or latest_date is None:
        return

    day = latest_date.date() if hasattr(latest_date, "date") else latest_date
    block = int(np.busday_count("2020-01-01", str(day)) // 10)
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    dxy, us10y_macro = macro_returns("DXY"), macro_returns("US10Y")
    factor_values = {str(x["factor_id"]): {} for x in ensemble}
    for symbol, r in returns.items():
        v20 = max(np.std(r[-21:-1]), .008)
        v60 = max(np.std(r[-61:-1]), .008)
        neg15 = r[-16:-1][r[-16:-1] < 0]
        neg60 = r[-61:-1][r[-61:-1] < 0]
        # All inputs are lagged to the last completed daily bar.
        values = {
            "miner_1_vol_adjusted_momentum_60d": np.sum(r[-60:]) / v60,
            "miner_3_vol_scaled_consistency_40d": np.mean(r[-40:] > 0) * np.sum(r[-40:]) / v60,
            "miner_1_relative_momentum_40d": np.sum(r[-40:]) / v60,
            "miner_2_20270422_vol_adjusted_momentum_20d": np.sum(r[-20:]) / v20,
            "miner_2_20270311_downside_vol_ratio_15_60": (np.std(neg15) / max(np.std(neg60), .008)) if len(neg15) >= 3 and len(neg60) >= 5 else np.nan,
            "miner_3_bear_breadth_reversal_1d": -r[-1] / v20 if r[-1] < 0 else 0.0,
            "miner_3_dxy_shock_reversal_1d": shock_reversal(r, dxy),
            "miner_3_us10y_shock_reversal_1d": shock_reversal(r, us10y_macro),
            "miner_2_downside_adjusted_momentum_30d": np.sum(r[-30:]) / max(np.std(r[-31:-1][r[-31:-1] < 0]), .008),
            "miner_1_drawdown_recovery_10d": r[-1] / max(abs(np.min(r[-11:-1])), .008),
        }
        for fid in factor_values:
            factor_values[fid][symbol] = values.get(fid, np.nan)

    factor_ids = [str(x["factor_id"]) for x in ensemble]
    score = {s: 0.5 for s in UNIVERSE}
    for item in ensemble:
        ranked = rank_cs(factor_values[str(item["factor_id"])])
        for s in UNIVERSE:
            score[s] += float(item["weight"]) * int(item.get("direction", 1)) * (ranked[s] - .5)

    # Bear correction: remain fully invested but favor gold and the two rate benchmarks.
    spx = returns.get("SPX")
    stressed = spx is not None and (np.sum(spx[-20:]) < 0 or np.std(spx[-20:]) > .02)
    if stressed:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .14
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= .06

    invvol = {s: 1.0 / max(np.std(returns[s][-20:]), .008) for s in returns}
    avg_invvol = float(np.mean(list(invvol.values())))
    raw = {s: max(.03, score[s]) * (.85 + .15 * invvol.get(s, avg_invvol) / avg_invvol) for s in UNIVERSE}
    weights = bounded_weights(raw)
    mean_score, sd_score = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-9)
    forecasts = {s: float(.01 * (score[s] - mean_score) / sd_score) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecasts, factor_ids=factor_ids, horizon_days=10)

