import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def rank_cs(values):
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / len(valid)
    return out


def bounded_weights(raw):
    # A complete long-only vector: 2% floor, 14% cap, and exactly 100% invested.
    w = {s: min(.14, max(.02, float(raw.get(s, .02)))) for s in UNIVERSE}
    for _ in range(100):
        gap = sum(w.values()) - 1.0
        if abs(gap) < 1e-12:
            break
        free = [s for s in UNIVERSE if (.0200001 < w[s] < .1399999) or
                (gap > 0 and w[s] > .0200001) or (gap < 0 and w[s] < .1399999)]
        if not free:
            break
        delta = gap / len(free)
        for s in free:
            w[s] = min(.14, max(.02, w[s] - delta))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble:
        return

    data, rets = {}, {}
    dates = []
    for s in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=s, days=160)
            if df is None or len(df) < 70:
                continue
            df = df.sort_values("date").reset_index(drop=True)
            close = np.asarray(df["close"], dtype=float)
            rets[s] = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
            data[s] = df
            dates.append(df.iloc[-1]["date"])
        except Exception:
            pass
    if len(rets) < 12 or not dates:
        return
    d = max(dates)
    d = d.date() if hasattr(d, "date") else d
    block = int(np.busday_count("2020-01-01", str(d)) // 10)
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    ids = [str(x["factor_id"]) for x in ensemble]
    vals = {fid: {} for fid in ids}
    for s, r in rets.items():
        # Signals are lagged one completed session: exclude r[-1].
        r30, r60 = r[-31:-1], r[-61:-1]
        r20 = r[-21:-1]
        v20 = max(float(np.std(r20)), .008)
        v60 = max(float(np.std(r60)), .008)
        neg = r60[r60 < 0]
        dvol = max(float(np.std(neg)) if len(neg) >= 3 else v60, .008)
        r10 = r[-11:-1]
        neg10 = r10[r10 < 0]
        short_dvol = max(float(np.std(neg10)) if len(neg10) >= 3 else v20, .008)
        ratio = np.clip(dvol / short_dvol, .5, 2.0)
        raw = {
            "miner_2_downside_adjusted_momentum_30d": np.sum(r30) / dvol,
            "miner_3_downside_shock_reversal_2d": -np.sum(r[-3:-1]) / v20,
            "miner_3_downside_shock_reversal_4d": -np.sum(r[-5:-1]) / v20 * ratio,
            "miner_2_directional_persistence_30d": np.mean(r30 > 0) * np.sum(r30) / v20,
            "miner_1_trend_consistency_60d": np.mean(r60 > 0) * np.sum(r60) / v60,
            "miner_2_20280323_tail_adjusted_momentum_30d": np.sum(r30) / dvol,
        }
        df = data[s]
        c = np.asarray(df["close"], dtype=float)
        hi = np.asarray(df["high"], dtype=float)
        lo = np.asarray(df["low"], dtype=float)
        tr = np.maximum(hi[1:] - lo[1:], np.maximum(abs(hi[1:] - c[:-1]), abs(lo[1:] - c[:-1]))) / np.maximum(c[1:], 1e-12)
        range20 = max(float(np.mean(tr[-21:-1])), .008)
        raw["range_reversal_3d"] = -np.sum(r[-4:-1]) / range20
        for item in ensemble:
            fid = str(item["factor_id"])
            vals[fid][s] = float(raw.get(fid, 0.0))

    scores = {s: .5 for s in UNIVERSE}
    for item in ensemble:
        fid = str(item["factor_id"])
        rr = rank_cs(vals[fid])
        for s in UNIVERSE:
            scores[s] += float(item["weight"]) * int(item.get("direction", 1)) * (rr[s] - .5)

    spx = rets.get("SPX", np.array([]))
    stressed = len(spx) >= 20 and (np.sum(spx[-21:-1]) < 0 or np.std(spx[-21:-1]) > .02)
    if stressed:
        for s in ("XAU", "US10Y", "CN10Y"):
            scores[s] += .14
        for s in ("BTC", "ETH", "WTI"):
            scores[s] -= .06

    inv = {s: 1.0 / max(float(np.std(rets[s][-21:-1])), .008) for s in UNIVERSE}
    mean_inv = np.mean(list(inv.values()))
    raw_w = {s: max(.03, scores[s]) * (.85 + .15 * inv[s] / mean_inv) for s in UNIVERSE}
    weights = bounded_weights(raw_w)
    center, scale = np.mean(list(scores.values())), max(np.std(list(scores.values())), 1e-9)
    forecasts = {s: float(.01 * (scores[s] - center) / scale) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecasts, factor_ids=ids, horizon_days=10)

