ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def cs_rank(values):
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out


def bounded(raw):
    w = {s: min(0.14, max(0.02, float(raw.get(s, 0.02)))) for s in UNIVERSE}
    for _ in range(80):
        gap = sum(w.values()) - 1.0
        if abs(gap) < 1e-10:
            break
        if gap > 0:
            pool = [s for s in UNIVERSE if w[s] > 0.020001]
        else:
            pool = [s for s in UNIVERSE if w[s] < 0.139999]
        if not pool:
            break
        for s in pool:
            w[s] = min(0.14, max(0.02, w[s] - gap / len(pool)))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble:
        return
    data, returns = {}, {}
    for s in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=s, days=180)
            if df is None or len(df) < 75:
                continue
            df = df.sort_values("date").reset_index(drop=True)
            close = np.asarray(df["close"], dtype=float)
            data[s] = df
            returns[s] = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
        except Exception:
            pass
    if len(returns) < 12:
        return
    last_date = data[next(iter(data))].iloc[-1]["date"]
    last_date = last_date.date() if hasattr(last_date, "date") else last_date
    block = int(np.busday_count("2020-01-01", str(last_date)) // 10)
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    ids = [str(x["factor_id"]) for x in ensemble]
