        df = data[s]
        close = np.asarray(df["close"], dtype=float)
        high = np.asarray(df["high"], dtype=float)
        low = np.asarray(df["low"], dtype=float)
        tr = np.maximum(high[1:] - low[1:], np.maximum(abs(high[1:] - close[:-1]), abs(low[1:] - close[:-1]))) / np.maximum(close[1:], 1e-12)
        clv = ((close[-6:-1] - low[-6:-1]) - (high[-6:-1] - close[-6:-1])) / np.maximum(high[-6:-1] - low[-6:-1], 1e-12)
        raw = {
            "miner_2_downside_adjusted_momentum_30d": np.sum(r30) / dvol,
            "miner_2_directional_persistence_30d": np.mean(r30 > 0) * np.sum(r30) / v20,
            "miner_1_trend_consistency_60d": np.mean(r60 > 0) * np.sum(r60) / v60,
            "miner_3_downside_shock_reversal_4d": -np.sum(r[-5:-1]) / v20 * shock_ratio,
            "miner_3_downside_shock_reversal_2d": -np.sum(r[-3:-1]) / v20,
            "miner_2_20280323_tail_adjusted_momentum_30d": np.sum(r30) / dvol,
            "miner_2_acceleration_reversal_40d": -(np.sum(r[-11:-1]) / v20 - np.sum(r[-41:-11]) / max(v60, .008)),
            "miner_3_clv_persistence_5d": float(np.mean(clv) * np.mean(clv > 0)),
        }
        for item in ensemble:
