        for s in ("BTC", "ETH", "WTI"):
            scores[s] -= 0.05

    invvol = {s: 1.0 / max(float(np.std(returns[s][-21:-1])), .008) for s in UNIVERSE}
    avg_inv = np.mean(list(invvol.values()))
    raw_weights = {s: max(.03, scores[s]) * (.85 + .15 * invvol[s] / avg_inv) for s in UNIVERSE}
    weights = bounded(raw_weights)
    center, dispersion = np.mean(list(scores.values())), max(np.std(list(scores.values())), 1e-9)
    forecasts = {s: float(.01 * (scores[s] - center) / dispersion) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecasts, factor_ids=ids, horizon_days=10)

