    n = len(finite)
    if n:
        for i, (s, _) in enumerate(finite):
            out[s] = (i + 1.0) / n
    return out


def bounded_weights(raw):
    # Feasible 15-asset long-only allocation: 2%-14% per asset.
    w = {s: min(0.14, max(0.02, float(raw.get(s, 0.02)))) for s in UNIVERSE}
    for _ in range(100):
        gap = sum(w.values()) - 1.0
        if abs(gap) < 1e-10:
            break
        if gap > 0:
            a = [s for s in UNIVERSE if w[s] > 0.020001]
        else:
            a = [s for s in UNIVERSE if w[s] < 0.139999]
        if not a:
            break
        step = gap / len(a)
        for s in a:
            w[s] = min(0.14, max(0.02, w[s] - step))
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


