import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def cross_rank(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if valid:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.0) / len(valid)
    return out


def bounded_weights(raw):
    w = {s: min(0.14, max(0.02, float(raw.get(s, 0.02)))) for s in UNIVERSE}
    for _ in range(200):
        gap = sum(w.values()) - 1.0
        if abs(gap) < 1e-11:
            break
        if gap > 0:
            active = [s for s in UNIVERSE if w[s] > 0.020001]
        else:
            active = [s for s in UNIVERSE if w[s] < 0.139999]
        if not active:
            break
        for s in active:
            w[s] = min(0.14, max(0.02, w[s] - gap / len(active)))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble:
        return
    factor_ids = [str(x["factor_id"]) for x in ensemble]
    data, rets = {}, {}
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=190)
            if df is None or len(df) < 100:
                continue
            df = df.sort_values("date").reset_index(drop=True)
            close = np.asarray(df["close"], dtype=float)
            r = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
            data[symbol], rets[symbol] = df, r
        except Exception:
            continue
    if len(rets) < 12:
        return

    date_text = str(data[next(iter(data))].iloc[-1]["date"])[:10]
    block = int(np.busday_count("2020-01-01", date_text) // 10)
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    factors = {str(x["factor_id"]): {} for x in ensemble}
    for s, r in rets.items():
        r10, r20, r30, r40, r60 = r[-11:-1], r[-21:-1], r[-31:-1], r[-41:-1], r[-61:-1]
        v20 = max(float(np.std(r20)), 0.008)
        v60 = max(float(np.std(r60)), 0.008)
        neg = r60[r60 < 0]
        downside = max(float(np.std(neg)) if len(neg) >= 3 else v60, 0.008)
        # Range location uses only the completed 60-day window and is a bounded confirmation.
        prices = np.asarray(data[s]["close"], dtype=float)
        w60 = prices[-61:-1]
        loc = (prices[-2] - np.min(w60)) / max(np.max(w60) - np.min(w60), 1e-12)
        trail = np.cumprod(1.0 + r[-90:])
        trough = float(np.min(trail / np.maximum.accumulate(trail) - 1.0))
        f = {
            "miner_2_downside_adjusted_momentum_30d": np.sum(r30) / downside,
            "miner_1_vol_adjusted_momentum_60d": np.sum(r60) / v60,
            "miner_3_risk_adjusted_momentum_10d": np.sum(r10) / max(float(np.std(r10)), 0.008),
            "miner_1_relative_momentum_40d": np.sum(r40),
            "miner_1_vol_regime_momentum_20d": np.sum(r20) / v20 * np.clip(0.015 / v20, 0.5, 1.5),
            "miner_1_recovery_90d": (np.sum(r[-90:]) - min(trough, 0.0)) / v60,
            "miner_2_range_location_momentum_10d": (np.sum(r10) / max(float(np.std(r10)), 0.008)) * (0.5 + 0.5 * loc),
            "range_reversal_3d": -np.sum(r[-4:-1]) / v20,
        }
        for fid in factors:
            factors[fid][s] = f.get(fid, 0.0)

    scores = {s: 0.5 for s in UNIVERSE}
    for item in ensemble:
        ranks = cross_rank(factors[item["factor_id"]])
        for s in UNIVERSE:
            scores[s] += float(item["weight"]) * int(item.get("direction", 1)) * (ranks[s] - 0.5)

    # High-risk sideways/bearish regime: retain full investment but favor defensive tradables.
    eq = [rets[s] for s in ("SPX", "000300.SH", "SX5E", "N225") if s in rets]
    breadth = float(np.mean([np.sum(x[-21:-1]) > 0 for x in eq])) if eq else 0.5
    high_vol = "SPX" in rets and float(np.std(rets["SPX"][-21:-1])) > 0.02
    if breadth < 0.5 or high_vol:
        for s in ("XAU", "US10Y", "CN10Y"):
            scores[s] += 0.12
        for s in ("BTC", "ETH", "WTI"):
            scores[s] -= 0.05

    vols = {s: max(float(np.std(rets[s][-21:-1])), 0.008) for s in rets}
    avg_vol = float(np.mean(list(vols.values())))
    raw = {s: max(0.03, scores[s]) * (0.85 + 0.15 * avg_vol / vols.get(s, avg_vol)) for s in UNIVERSE}
    weights = bounded_weights(raw)
    mean_score = float(np.mean(list(scores.values())))
    scale = max(float(np.std(list(scores.values()))), 1e-9)
    forecasts = {s: float(0.01 * (scores[s] - mean_score) / scale) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecasts, factor_ids=factor_ids, horizon_days=10)

