ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def percentile_rank(values):
    good = [(s, float(v)) for s, v in values.items() if np.isfinite(v)]
    good.sort(key=lambda z: z[1])
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / n
    return out


def bounded(raw):
    # 15-asset, fully invested long-only portfolio; no cash sleeve.
    w = {s: min(0.14, max(0.02, float(raw.get(s, 0.02)))) for s in UNIVERSE}
    for _ in range(1000):
        gap = sum(w.values()) - 1.0
        if abs(gap) < 1e-11:
            break
        free = [s for s in UNIVERSE if (w[s] > .020001 if gap > 0 else w[s] < .139999)]
        if not free:
            break
        for s in free:
            w[s] = min(.14, max(.02, w[s] - gap / len(free)))
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


