    block = int(np.busday_count("2020-01-01", date_text) // 10)
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    # Factor proxies use only completed daily bars. They preserve the screener IDs,
    # directions, and weights while remaining robust to the small 15-asset universe.
    raw_factor = {f["factor_id"]: {} for f in ensemble}
