            "miner_1_relative_momentum_40d": np.sum(r40),
            "miner_3_relative_residual_momentum_20d": np.sum(r[-21:-1]) / v20 - cross_median / v20,
            "miner_3_sign_consistency_momentum_10d": (np.sum(r10) / v10) * abs(np.mean(np.sign(r10))),
