    except Exception:
        return []

def rank(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    n = len(good)
    if n:
        for i, (s, _) in enumerate(good): out[s] = (i + 1.) / n
    return out

def normalize(raw):
    w = {s: min(.14, max(.02, float(raw.get(s, .02)))) for s in UNIVERSE}
    for _ in range(100):
        gap = sum(w.values()) - 1.
        if abs(gap) < 1e-12: break
        free = [s for s in UNIVERSE if (.020001 < w[s] < .139999)]
        if not free: break
        for s in free: w[s] = min(.14, max(.02, w[s] - gap / len(free)))
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}

@register_hook
