import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def rank_map(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if valid:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.0) / len(valid)
    return out


def full_weights(scores):
    # Full investment, long-only; defensive risk control is expressed by ranks,
    # volatility scaling and explicit tradable defensive assets.
    raw = {s: max(0.03, float(scores.get(s, 0.5))) for s in UNIVERSE}
    w = {s: min(0.14, raw[s]) for s in UNIVERSE}
    for _ in range(100):
        gap = sum(w.values()) - 1.0
        free = [s for s in UNIVERSE if 0.030001 < w[s] < 0.139999]
        if abs(gap) < 1e-10 or not free:
            break
        for s in free:
            w[s] = min(0.14, max(0.03, w[s] - gap / len(free)))
    total = sum(w.values())
    return {s: float(w[s] / total) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble:
        return
    factor_ids = [str(f["factor_id"]) for f in ensemble]
    rets = {}
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=220)
            if df is None or len(df) < 100:
                continue
            close = np.asarray(df.sort_values("date")["close"], dtype=float)
            rets[symbol] = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
        except Exception:
            continue
    if len(rets) < 12:
        return
    # The simulator invokes this daily; only one target is proposed per 10-day block.
    sample = next(iter(rets.values()))
    block = int(np.busday_count("2020-01-01", str(len(sample))) // 10)
    # Use the latest completed-date ordinal, not intraday data. A stable date gate is
    # reconstructed from the common daily history length in this synthetic worldline.
    block = int(len(sample) // 10)
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    factor_values = {f["factor_id"]: {} for f in ensemble}
    for symbol, r in rets.items():
        r10, r20, r30, r40, r60 = r[-11:-1], r[-21:-1], r[-31:-1], r[-41:-1], r[-61:-1]
        v10 = max(float(np.std(r10)), 0.008)
        v20 = max(float(np.std(r20)), 0.008)
        v60 = max(float(np.std(r60)), 0.008)
        neg = r60[r60 < 0]
        down = max(float(np.std(neg)) if len(neg) >= 3 else v60, 0.008)
        factor_values_for_symbol = {
            "miner_2_downside_adjusted_momentum_30d": np.sum(r30) / down,
            "miner_1_vol_adjusted_momentum_60d": np.sum(r60) / v60,
            "miner_1_directional_efficiency_20d": abs(np.sum(r20)) / max(np.sum(abs(r20)), 0.01),
            "miner_1_relative_momentum_40d": np.sum(r40),
            "miner_3_vol_regime_consistency_momentum_20d": (np.sum(r20) / v20) * np.clip(0.018 / v20, 0.5, 1.2),
            "miner_2_20281130_vix_conditioned_sign_momentum_10d": np.sum(r10) / v10 * (0.6 + 0.4 * abs(np.mean(np.sign(r10)))),
            "miner_1_recovery_90d": np.sum(r[-90:]) / v60,
            "miner_2_range_location_momentum_10d": (np.sum(r10) + r[-1]) / v10,
        }
        for f in ensemble:
            factor_values[f["factor_id"]][symbol] = factor_values_for_symbol.get(f["factor_id"], 0.0)

    scores = {s: 0.5 for s in UNIVERSE}
    for f in ensemble:
        ranked = rank_map(factor_values[f["factor_id"]])
        for s in UNIVERSE:
            scores[s] += float(f["weight"]) * int(f.get("direction", 1)) * (ranked[s] - 0.5)

    eq = [np.sum(rets[s][-21:-1]) > 0 for s in ("SPX", "000300.SH", "SX5E", "N225") if s in rets]
    stressed = (eq and np.mean(eq) < 0.5) or ("SPX" in rets and np.std(rets["SPX"][-21:-1]) > 0.02)
    if stressed:
        for s in ("XAU", "US10Y", "CN10Y"):
            scores[s] += 0.12
        for s in ("BTC", "ETH", "WTI"):
            scores[s] -= 0.05

    vols = {s: max(float(np.std(rets[s][-21:-1])), 0.008) for s in rets}
    average_vol = float(np.mean(list(vols.values())))
    scores = {s: scores[s] * (0.85 + 0.15 * average_vol / vols.get(s, average_vol)) for s in UNIVERSE}
    target = full_weights(scores)
    mean = float(np.mean(list(scores.values())))
    stdev = max(float(np.std(list(scores.values()))), 1e-9)
    forecasts = {s: float(0.01 * (scores[s] - mean) / stdev) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecasts, factor_ids=factor_ids, horizon_days=10)

