import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def rank_map(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / len(valid)
    return out


def full_weights(scores):
    # A complete, long-only, no-cash vector. Bounds prevent concentration in
    # unstable crypto/commodity reversals while retaining defensive instruments.
    lo, hi = 0.03, 0.14
    w = {s: min(hi, max(lo, float(scores.get(s, 0.5)))) for s in UNIVERSE}
    for _ in range(100):
        gap = sum(w.values()) - 1.0
        free = [s for s in UNIVERSE if lo + 1e-8 < w[s] < hi - 1e-8]
        if abs(gap) < 1e-10 or not free:
            break
        for s in free:
            w[s] = min(hi, max(lo, w[s] - gap / len(free)))
    total = sum(w.values())
    return {s: float(w[s] / total) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble:
        return
    factor_ids = [str(f["factor_id"]) for f in ensemble]
    rets = {}
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=220)
            if df is None or len(df) < 100:
