UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def rank(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1) / n if n else 0.5
    return out


def bounded_weights(score):
    # Full investment, with sensible diversification for a 15-asset universe.
    lo, hi = 0.03, 0.14
    w = {s: lo + (hi - lo) * np.clip(score.get(s, .5), 0.0, 1.0) for s in UNIVERSE}
    for _ in range(20):
        total = sum(w.values())
        w = {s: x / total for s, x in w.items()}
        high = [s for s in UNIVERSE if w[s] > hi + 1e-12]
        low = [s for s in UNIVERSE if w[s] < lo - 1e-12]
        if high:
            excess = sum(w[s] - hi for s in high)
            for s in high: w[s] = hi
            free = [s for s in UNIVERSE if s not in high]
            for s in free: w[s] += excess / len(free)
        elif low:
            deficit = sum(lo - w[s] for s in low)
            for s in low: w[s] = lo
            free = [s for s in UNIVERSE if s not in low]
            for s in free: w[s] -= deficit / len(free)
        else:
            break
    total = sum(w.values())
    return {s: float(w[s] / total) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble or len(ensemble) > 10:
        return
    factor_ids = [str(f["factor_id"]) for f in ensemble]
    series = {}
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=220)
            if df is not None and len(df) >= 100:
                close = np.asarray(df.sort_values("date")["close"], dtype=float)
                series[symbol] = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
        except Exception:
            continue
    if len(series) < 12:
        return
    block = len(next(iter(series.values()))) // 10
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    equities = [s for s in ("000300.SH", "SPX", "SX5E", "N225") if s in series]
    market5 = float(np.mean([np.sum(series[s][-6:-1]) for s in equities])) if equities else 0.0
    values = {fid: {} for fid in factor_ids}
    for symbol, r in series.items():
        r5, r10, r20 = r[-6:-1], r[-11:-1], r[-21:-1]
        r40, r60, r90 = r[-41:-1], r[-61:-1], r[-91:-1]
        v10 = max(float(np.std(r10)), .008)
        v20 = max(float(np.std(r20)), .008)
        v60 = max(float(np.std(r60)), .008)
        downside = max(float(np.std(r60[r60 < 0])) if np.sum(r60 < 0) >= 3 else v60, .008)
        t10, t20, t40 = float(np.sum(r10)), float(np.sum(r20)), float(np.sum(r40))
        t60, t90 = float(np.sum(r60)), float(np.sum(r90))
        efficiency = abs(t20) / max(float(np.sum(np.abs(r20))), 1e-8)
        # These are deliberately simple trailing proxies; all observations end at t-1.
        proxy = {
            "miner_3_vol_scaled_consistency_40d": t40 / v60 * (1 - min(1, np.std(r40) / .04)),
            "miner_2_downside_adjusted_momentum_30d": float(np.sum(r[-31:-1])) / downside,
            "miner_2_20290125_trend_agreement_10d": float(t10 > 0) + float(t20 > 0) + float(t40 > 0),
            "miner_1_relative_momentum_40d": t40,
            "miner_2_20290517_residual_relative_reversal_20d": -t20 / v20,
            "miner_1_directional_efficiency_20d": efficiency * np.sign(t20),
            "miner_1_20290405_defensive_relative_strength_5d": float(np.sum(r5) - market5),
            "miner_2_20290531_range_efficiency_reversal_20d": -t20 / max(efficiency, .10) / v20,
        }
        for fid in factor_ids:
            values[fid][symbol] = proxy.get(fid, 0.0)

    score = {s: 0.5 for s in UNIVERSE}
    for factor in ensemble:
        rr = rank(values[str(factor["factor_id"])])
        for s in UNIVERSE:
            score[s] += float(factor["weight"]) * int(factor.get("direction", 1)) * (rr[s] - .5)

    # High-risk rebound overlay: defensive tradable assets, never cash.
    eq21 = float(np.mean([np.sum(series[s][-21:-1]) for s in equities])) if equities else 0.0
    eqvol = float(np.mean([np.std(series[s][-21:-1]) for s in equities])) if equities else .02
    if eq21 < 0 or (market5 > .02 and eqvol > .012):
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .10
        for s in ("BTC", "ETH", "WTI", "SOX", "NDX"):
            score[s] -= .04

    vol = {s: max(float(np.std(r[-21:-1])), .008) for s, r in series.items()}
    avgvol = float(np.mean(list(vol.values())))
    score = {s: score[s] * (.88 + .12 * avgvol / vol.get(s, avgvol)) for s in UNIVERSE}
    mean = float(np.mean(list(score.values())))
    sd = max(float(np.std(list(score.values()))), 1e-9)
    target = bounded_weights(score)
    forecast_returns = {s: float(.01 * (score[s] - mean) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10)
