import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factor_ensemble.json"
LAST_BLOCK = None

def load_ensemble():
    try:
        x = json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])
        return x[:10] if len(x) <= 10 else []
    except Exception:
        return []

def ranks(x):
    good = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    if good:
        for i, (s, _) in enumerate(good): out[s] = (i + 1) / len(good)
    return out

def weights(score):
    # Full-investment, small-universe diversification; no cash sleeve.
    lo, hi = .03, .14
    w = {s: lo + (hi-lo)*np.clip(score.get(s, .5), 0., 1.) for s in UNIVERSE}
    for _ in range(20):
        z = sum(w.values()); w = {s: v/z for s,v in w.items()}
        high = [s for s in UNIVERSE if w[s] > hi]
        low = [s for s in UNIVERSE if w[s] < lo]
        if high:
            excess = sum(w[s]-hi for s in high)
            for s in high: w[s] = hi
            for s in UNIVERSE:
                if s not in high: w[s] += excess/(len(UNIVERSE)-len(high))
        elif low:
            deficit = sum(lo-w[s] for s in low)
            for s in low: w[s] = lo
            for s in UNIVERSE:
                if s not in low: w[s] -= deficit/(len(UNIVERSE)-len(low))
        else: break
    z = sum(w.values())
    return {s: float(max(0., w[s])/z) for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble: return
    factor_ids = [str(f["factor_id"]) for f in ensemble]
    series, last_date = {}, None
    for s in UNIVERSE:
        try:
            d = get_stock_daily_data(symbol=s, days=220)
            if d is not None and len(d) >= 100:
                d = d.sort_values("date")
                c = np.asarray(d["close"], dtype=float)
                series[s] = c[1:] / np.maximum(c[:-1], 1e-12) - 1.
                last_date = d.iloc[-1]["date"]
        except Exception:
            pass
    if len(series) < 12: return
    # Stable deterministic ten-trading-day gate (the simulator invokes daily).
    try: block = int(last_date.toordinal()) // 14
    except Exception: block = len(next(iter(series.values()))) // 10
    if block == LAST_BLOCK: return
    LAST_BLOCK = block
    eq = [s for s in ("000300.SH","SPX","SX5E","N225") if s in series]
    market10 = np.mean([np.sum(series[s][-11:-1]) for s in eq]) if eq else 0.
    vals = {str(f["factor_id"]): {} for f in ensemble}
    for s,r in series.items():
        r10,r20,r30,r40,r60 = r[-11:-1],r[-21:-1],r[-31:-1],r[-41:-1],r[-61:-1]
        v10=max(np.std(r10),.008); v20=max(np.std(r20),.008); v40=max(np.std(r40),.008)
        down=max(np.std(r30[r30<0]) if np.sum(r30<0)>=3 else np.std(r30),.008)
        t10,t20,t30,t40 = np.sum(r10),np.sum(r20),np.sum(r30),np.sum(r40)
        # Robust lagged proxies matching the persisted factor intents.
        med20=np.median([np.sum(x[-21:-1]) for x in series.values()])
        residual=t40-(np.cov(r40, np.mean([x[-41:-1] for x in series.values()],axis=0))[0,1]/max(np.var(np.mean([x[-41:-1] for x in series.values()],axis=0)),1e-8))*np.mean([np.sum(x[-41:-1]) for x in series.values()])
        sign=.5+.5*abs(2*np.mean(r20>0)-1)
        proxy={
          "miner_2_downside_adjusted_momentum_30d": t30/down,
          "miner_2_20290614_shock_recovery_quality_10d": (-min(0.,np.min(r10))+max(0.,t10))/v10,
          "miner_2_20290531_range_efficiency_reversal_20d": -t20/(max(abs(t20)/max(np.sum(abs(r20)),1e-8),.1)*v20),
          "miner_2_20290517_residual_relative_reversal_20d": -residual/v40,
          "miner_2_20290125_trend_agreement_10d": (np.sign(t10)+np.sign(t20)+np.sign(np.sum(r[-60:-1])))/3.*t20/v40,
          "miner_2_20290628_dispersion_adjusted_recovery_10d": (t10-med20)/(0.01+abs(np.sum(np.minimum(r30,0))))/np.sqrt(1+max(t30,0)/(0.01+abs(np.sum(np.minimum(r30,0))))),
          "miner_2_20281228_vol_regime_consistency_momentum_10d": (t20/(v20*np.sqrt(20)))*sign,
          "miner_2_20281116_sign_consistency_momentum_10d": (t20/(v40*np.sqrt(20)))*sign,
        }
        for f in vals: vals[f][s] = float(proxy.get(f,0.))
    score={s:.5 for s in UNIVERSE}
    for f in ensemble:
        rr=ranks(vals[f["factor_id"]])
        for s in UNIVERSE: score[s] += float(f["weight"])*int(f.get("direction",1))*(rr[s]-.5)
    # High-risk sideways/bearish overlay: use tradable defensive assets, never cash.
    eq21=np.mean([np.sum(series[s][-21:-1]) for s in eq]) if eq else 0.
    eqvol=np.mean([np.std(series[s][-21:-1]) for s in eq]) if eq else .02
    if eq21 < 0 or (market10 > .015 and eqvol > .012):
        for s in ("XAU","US10Y","CN10Y"): score[s] += .10
        for s in ("BTC","ETH","WTI","SOX","NDX"): score[s] -= .04
    vol={s:max(np.std(r[-21:-1]),.008) for s,r in series.items()}; av=np.mean(list(vol.values()))
    score={s:score[s]*(.88+.12*av/vol.get(s,av)) for s in UNIVERSE}
    mean=np.mean(list(score.values())); sd=max(np.std(list(score.values())),1e-9)
    target=weights(score)
    forecast={s:float(.01*(score[s]-mean)/sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

