    w = {s: 0.03 + 0.11 * np.clip(score.get(s, 0.5), 0, 1) for s in UNIVERSE}
    for _ in range(15):
        z = sum(w.values())
        w = {s: x / z for s, x in w.items()}
        hi = [s for s in UNIVERSE if w[s] > 0.14]
        if not hi: break
        excess = sum(w[s] - 0.14 for s in hi)
        for s in hi: w[s] = 0.14
        others = [s for s in UNIVERSE if s not in hi]
        for s in others: w[s] += excess / len(others)
    z = sum(w.values())
    return {s: float(w[s] / z) for s in UNIVERSE}

