LAST_BLOCK = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def rank_cs(values):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out


def make_weights(score):
    # Full investment, modest concentration, and no cash sleeve.
    w = {s: 0.03 + 0.11 * np.clip(score.get(s, 0.5), 0.0, 1.0) for s in UNIVERSE}
    for _ in range(20):
        total = sum(w.values())
        w = {s: x / total for s, x in w.items()}
        high = [s for s in UNIVERSE if w[s] > 0.14]
        if not high:
            break
        excess = sum(w[s] - 0.14 for s in high)
        for s in high:
            w[s] = 0.14
        for s in UNIVERSE:
            if s not in high:
                w[s] += excess / (len(UNIVERSE) - len(high))
    total = sum(w.values())
    return {s: float(w[s] / total) for s in UNIVERSE}


