import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def rank_cs(x):
    out = {s: 0.5 for s in UNIVERSE}
    a = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    for i, (s, _) in enumerate(a):
        out[s] = (i + 1.0) / len(a)
    return out


def make_weights(score):
    # Smooth full-investment allocation, with a defensive bearish overlay.
    z = np.array([score[s] for s in UNIVERSE], dtype=float)
    z = np.clip(z - z.min() + 0.35, 0.35, None)
    w = z / z.sum()
    # Iterative capped simplex projection: 3% minimum, 14% maximum.
    w = np.maximum(w, 0.03)
    w /= w.sum()
    for _ in range(20):
        over = w > 0.14
        excess = float(np.sum(w[over] - 0.14))
        w[over] = 0.14
        under = ~over
        if excess <= 1e-10:
            break
        w[under] += excess / max(int(np.sum(under)), 1)
    w = np.maximum(w, 0.03)
    return {s: float(v / w.sum()) for s, v in zip(UNIVERSE, w)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble or len(ensemble) > 10:
        return
    factor_ids = [f["factor_id"] for f in ensemble]
    directions = {f["factor_id"]: int(f.get("direction", 1)) for f in ensemble}
    returns, last_date = {}, None
    for s in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=s, days=220)
            if df is not None and len(df) >= 130:
                df = df.sort_values("date")
                p = np.asarray(df["close"], dtype=float)
                returns[s] = p[1:] / np.maximum(p[:-1], 1e-12) - 1.0
                last_date = str(df.iloc[-1]["date"])[:10]
        except Exception:
            pass
    if len(returns) < 12 or last_date is None:
        return
    try:
        block = int(np.busday_count("2020-01-01", last_date) // 10)
    except Exception:
        block = 0
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    eq = [s for s in ("000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH") if s in returns]
    m10 = float(np.mean([np.sum(returns[s][-11:-1]) for s in eq])) if eq else 0.0
    m35 = float(np.mean([np.sum(returns[s][-36:-1]) for s in eq])) if eq else 0.0
    med20 = float(np.median([np.sum(r[-21:-1]) for r in returns.values()]))
    breadth = float(np.mean([np.sum(r[-21:-1]) > 0 for r in returns.values()]))
    med40 = float(np.median([np.sum(r[-41:-1]) for r in returns.values()]))
    raw = {f["factor_id"]: {} for f in ensemble}
    for s, r in returns.items():
        r10, r20, r30, r40 = r[-11:-1], r[-21:-1], r[-31:-1], r[-41:-1]
        v10, v20 = max(np.std(r10), .008), max(np.std(r20), .008)
        down = max(np.std(r30[r30 < 0]) if np.sum(r30 < 0) >= 3 else np.std(r30), .008)
        t10, t20, t30, t40 = map(np.sum, (r10, r20, r30, r40))
        regime = 1.0 + .6 * np.clip(v20 / max(np.std(r[-120:-1]), .008) - 1.0, -.5, 1.0)
        shock = max(0.0, -float(np.min(r10)))
        p = {
          "miner_3_bear_breadth_reversal_1d": -np.sign(t10) * (1.0 - breadth) * r[-2] / v10,
          "miner_2_downside_adjusted_momentum_30d": t30 / down,
          "miner_2_20290125_trend_agreement_10d": (np.sign(t10)+np.sign(t20)+np.sign(t30))*t20/(3*v20),
          "miner_2_20290614_shock_recovery_quality_10d": (max(0.0,t10)-shock)/v10,
          "miner_2_20290531_range_efficiency_reversal_20d": -t20/max(np.sum(np.abs(r20)), .01),
          "miner_1_relative_momentum_40d": t40-med40,
          "miner_1_directional_efficiency_20d": t20/max(np.sum(np.abs(r20)), .01),
          "miner_1_20291129_regime_gated_reversal_10d": -t10/(v20*np.sqrt(10)+.01)*regime,
        }
        for f in raw:
            raw[f][s] = float(p.get(f, 0.0))

    score = {s: 0.5 for s in UNIVERSE}
    for f in ensemble:
        rr = rank_cs(raw[f["factor_id"]])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * directions[f["factor_id"]] * (rr[s] - .5)
    if m10 < 0 and m35 < 0:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += .12
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"): score[s] -= .06
    elif m10 < 0 or m35 < 0:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += .07
    vol = {s: max(np.std(r[-21:-1]), .008) for s, r in returns.items()}
    av = float(np.mean(list(vol.values())))
    for s in UNIVERSE:
        score[s] *= .90 + .10 * av / vol.get(s, av)
    target = make_weights(score)
    mu, sd = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(.01 * (score[s] - mu) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

