from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def cs_rank(values):
    finite = [(s, float(v)) for s, v in values.items() if np.isfinite(v)]
    out = {s: 0.5 for s in UNIVERSE}
    if not finite:
        return out
    finite.sort(key=lambda x: x[1])
    for i, (s, _) in enumerate(finite):
        out[s] = (i + 1.0) / len(finite)
    return out


def bounded_weights(score):
    # Full investment, with diversified 3%-14% bounds for this 15-asset universe.
    w = np.array([max(float(score.get(s, 0.5)), 0.05) for s in UNIVERSE])
    w /= w.sum()
    for _ in range(30):
        high = w > 0.14
        excess = float(np.sum(w[high] - 0.14))
        w[high] = 0.14
        if excess <= 1e-10:
            break
        w[~high] += excess / max(int((~high).sum()), 1)
    w = np.maximum(w, 0.03)
    w /= w.sum()
    return {s: float(x) for s, x in zip(UNIVERSE, w)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble or len(ensemble) > 10:
        return
    factor_ids = [f["factor_id"] for f in ensemble]
    data = {}
    last_date = None
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=220)
            if df is not None and len(df) >= 130:
                df = df.sort_values("date")
                close = np.asarray(df["close"], dtype=float)
                data[symbol] = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
                last_date = str(df.iloc[-1]["date"])[:10]
        except Exception:
            continue
    if len(data) < 12 or not last_date:
        return
    try:
        block = int(np.busday_count("2020-01-01", last_date) // 10)
    except Exception:
        block = 0
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    equity = [s for s in ("000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH") if s in data]
    eq10 = float(np.mean([np.sum(data[s][-11:-1]) for s in equity])) if equity else 0.0
    eq35 = float(np.mean([np.sum(data[s][-36:-1]) for s in equity])) if equity else 0.0
    breadth = float(np.mean([np.sum(r[-21:-1]) > 0 for r in data.values()]))
    med40 = float(np.median([np.sum(r[-41:-1]) for r in data.values()]))
    raw = {f["factor_id"]: {} for f in ensemble}
    for symbol, r in data.items():
        r10, r20, r30, r40 = r[-11:-1], r[-21:-1], r[-31:-1], r[-41:-1]
        v10, v20 = max(np.std(r10), .008), max(np.std(r20), .008)
        downside = max(np.std(r30[r30 < 0]) if np.sum(r30 < 0) >= 3 else np.std(r30), .008)
        t10, t20, t30, t40 = map(np.sum, (r10, r20, r30, r40))
        values = {
            "miner_2_downside_adjusted_momentum_30d": t30 / downside,
            "miner_3_bear_breadth_reversal_1d": -np.sign(t10) * (1.0 - breadth) * r[-2] / v10,
            "miner_2_20290125_trend_agreement_10d": (np.sign(t10) + np.sign(t20) + np.sign(t30)) * t20 / (3.0 * v20),
            "miner_2_20290628_dispersion_adjusted_recovery_10d": t10 / v10,
            "miner_2_20290614_shock_recovery_quality_10d": max(0.0, t10) / v10,
            "miner_2_20290531_range_efficiency_reversal_20d": -t20 / max(np.sum(np.abs(r20)), .01),
            "miner_1_relative_momentum_40d": t40 - med40,
            "miner_1_directional_efficiency_20d": t20 / max(np.sum(np.abs(r20)), .01),
        }
        for f in raw:
            raw[f][symbol] = float(values.get(f, 0.0))

    score = {s: 0.5 for s in UNIVERSE}
    for f in ensemble:
        ranks = cs_rank(raw[f["factor_id"]])
        direction = int(f.get("direction", 1))
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * direction * (ranks[s] - 0.5)
    # Bear regime: defensive tradable assets replace a cash sleeve.
    if eq10 < 0 and eq35 < 0:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += 0.12
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"): score[s] -= 0.06
    elif eq10 < 0 or eq35 < 0:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += 0.07
    vol = {s: max(np.std(r[-21:-1]), .008) for s, r in data.items()}
    avg_vol = float(np.mean(list(vol.values())))
    for s in UNIVERSE:
        score[s] *= 0.90 + 0.10 * avg_vol / vol.get(s, avg_vol)
    target = bounded_weights(score)
    mean_score = float(np.mean(list(score.values())))
    sd = max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(0.01 * (score[s] - mean_score) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
"}

