from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def get_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def percentile(values):
    out = {s: 0.5 for s in UNIVERSE}
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    n = len(valid)
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / n if n else 0.5
    return out


def bounded_weights(scores):
    # Conservative long-only full-investment bounds for a 15-asset universe.
    w = np.array([max(0.03, float(scores.get(s, 0.5))) for s in UNIVERSE], dtype=float)
    w /= w.sum()
    for _ in range(30):
        excess = float(np.maximum(w - 0.14, 0.0).sum())
        if excess < 1e-10:
            break
        w = np.minimum(w, 0.14)
        free = w < 0.14 - 1e-10
        if not free.any():
            break
        w[free] += excess / free.sum()
    w = np.maximum(w, 0.03)
    w /= w.sum()
    return {s: float(x) for s, x in zip(UNIVERSE, w)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ens = get_ensemble()
    if not ens or len(ens) > 10:
        return
    factor_ids = [f["factor_id"] for f in ens]
    returns, last_date = {}, None
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=220)
            if df is not None and len(df) >= 130:
                df = df.sort_values("date")
                close = np.asarray(df["close"], dtype=float)
                returns[symbol] = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
                last_date = str(df.iloc[-1]["date"])[:10]
        except Exception:
            continue
    if len(returns) < 12 or last_date is None:
        return
    try:
        block = int(np.busday_count("2020-01-01", last_date) // 10)
    except Exception:
        block = 0
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    med40 = float(np.median([np.sum(r[-41:-1]) for r in returns.values()]))
    raw = {fid: {} for fid in factor_ids}
    for symbol, r in returns.items():
        r10, r20, r30, r40 = r[-11:-1], r[-21:-1], r[-31:-1], r[-41:-1]
        t10, t20, t30, t40 = map(np.sum, (r10, r20, r30, r40))
        v10, v20 = max(np.std(r10), .008), max(np.std(r20), .008)
        neg = r30[r30 < 0]
        downside = max(np.std(neg) if len(neg) >= 3 else np.std(r30), .008)
        raw_values = {
            "miner_2_downside_adjusted_momentum_30d": t30 / downside,
            "miner_3_20300124_trend_agreement_residual_10d": (np.sign(t10) + np.sign(t20) + np.sign(t30)) * t10 / (3 * v10),
            "miner_1_relative_momentum_40d": t40 - med40,
            "miner_1_20290920_regime_confirmed_momentum_10d": t10 / v10 if np.sign(t10) == np.sign(t30) else 0.0,
            "miner_2_20290614_shock_recovery_quality_10d": max(0.0, t10) / v10,
            "miner_3_vol_regime_consistency_momentum_20d": t20 / v20 * (1.0 - min(v20 / .10, 1.0)),
            "miner_2_20290531_range_efficiency_reversal_20d": -t20 / max(np.sum(np.abs(r20)), .01),
            "miner_2_20290628_dispersion_adjusted_recovery_10d": t10 / v10,
            "miner_1_directional_efficiency_20d": abs(t20) / max(np.sum(np.abs(r20)), .01) * np.sign(t20),
            "miner_1_vol_adjusted_momentum_60d": np.sum(r[-61:-1]) / max(np.std(r[-61:-1]), .008) if len(r) >= 61 else t40 / v20,
        }
        for fid in factor_ids:
            raw[fid][symbol] = raw_values.get(fid, 0.0)

    score = {s: 0.5 for s in UNIVERSE}
    for factor in ens:
        ranks = percentile(raw[factor["factor_id"]])
        for symbol in UNIVERSE:
            score[symbol] += float(factor["weight"]) * int(factor.get("direction", 1)) * (ranks[symbol] - 0.5)

    equities = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH"]
    eq = [np.sum(returns[s][-21:-1]) for s in equities if s in returns]
    medium = [np.sum(returns[s][-61:-1]) for s in equities if s in returns]
    if eq and np.mean(eq) < 0 and medium and np.mean(medium) < 0:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.12
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"):
            score[s] -= 0.06
    elif eq and np.mean(eq) < 0:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.07

    vol = {s: max(np.std(r[-21:-1]), .008) for s, r in returns.items()}
    avg_vol = float(np.mean(list(vol.values())))
    for s in UNIVERSE:
        score[s] *= 0.90 + 0.10 * avg_vol / vol.get(s, avg_vol)
    target = bounded_weights(score)
