    sd_score = max(float(np.std(list(score.values()))), 1e-9)
    forecast_returns = {s: float(0.01 * (score[s] - mean_score) / sd_score) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10)

