import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def ranks(values):
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(valid)
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / n if n else 0.5
    return out


def weights(score):
    # Full investment, diversified and deliberately conservative in stress.
    w = np.array([max(0.03, score.get(s, 0.5)) for s in UNIVERSE], float)
    w /= w.sum()
    for _ in range(20):
        high = w > 0.14
        if not high.any():
            break
        excess = float((w[high] - 0.14).sum())
        w[high] = 0.14
        free = ~high
        w[free] += excess / max(int(free.sum()), 1)
    w = np.maximum(w, 0.03)
    w /= w.sum()
    return {s: float(x) for s, x in zip(UNIVERSE, w)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ens = ensemble()
    if not ens or len(ens) > 10:
        return
    factor_ids = [f["factor_id"] for f in ens]
    series = {}
    for s in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=s, days=220)
            if df is not None and len(df) >= 65:
                c = np.asarray(df.sort_values("date")["close"], float)
                series[s] = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        except Exception:
            pass
    if len(series) < 12:
        return
    # Decisions are made once per ten-trading-day block.
    try:
        date = str(df.sort_values("date").iloc[-1]["date"])[:10]
        block = int(np.busday_count("2020-01-01", date) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    median40 = float(np.median([np.sum(r[-41:-1]) for r in series.values()]))
    raw = {f["factor_id"]: {} for f in ens}
    for s, r in series.items():
        r10, r20, r30, r40 = r[-11:-1], r[-21:-1], r[-31:-1], r[-41:-1]
        t10, t20, t30, t40 = map(np.sum, (r10, r20, r30, r40))
        v10, v20 = max(np.std(r10), .008), max(np.std(r20), .008)
        neg = r30[r30 < 0]
        down = max(np.std(neg) if len(neg) >= 3 else np.std(r30), .008)
        vals = {
            "miner_2_downside_adjusted_momentum_30d": t30 / down,
            "miner_1_relative_momentum_40d": t40 - median40,
            "miner_3_20300124_trend_agreement_residual_10d": (np.sign(t10) + np.sign(t20) + np.sign(t30)) * t10 / (3*v10),
            "miner_1_20290920_regime_confirmed_momentum_10d": t10 / v10 if np.sign(t10) == np.sign(t30) else 0.0,
            "miner_2_20300124_downside_sharpe_recovery_10d": max(0.0, t10) / down,
            # In the ensemble this factor has direction -1: lower defensive-trend score is favored.
            "miner_2_20300321_defensive_trend_10d": -(t20 / v20),
            "miner_3_20300321_trend_conditioned_momentum_10d": t10 / v10 if t30 < 0 else 0.0,
            "miner_2_20290531_range_efficiency_reversal_20d": -t20 / max(np.sum(np.abs(r20)), .01),
        }
        for fid in factor_ids:
            raw[fid][s] = vals.get(fid, 0.0)

    score = {s: 0.5 for s in UNIVERSE}
    for f in ens:
        rr = ranks(raw[f["factor_id"]])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * (rr[s] - 0.5)

    # Bear/high-volatility overlay: defensive tradable benchmarks, never cash.
    equities = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH"]
    eq20 = [np.sum(series[s][-21:-1]) for s in equities if s in series]
    eq60 = [np.sum(series[s][-61:-1]) for s in equities if len(series[s]) >= 61]
    if eq20 and np.mean(eq20) < 0:
        bump = 0.12 if eq60 and np.mean(eq60) < 0 else 0.07
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += bump
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"):
            score[s] -= bump * 0.5

    vol = {s: max(np.std(r[-21:-1]), .008) for s, r in series.items()}
    av = float(np.mean(list(vol.values())))
    for s in UNIVERSE:
        score[s] *= 0.90 + 0.10 * av / vol.get(s, av)
    target = weights(score)
    mu, sd = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-9)
    forecast_returns = {s: float(0.01 * (score[s] - mu) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10)

