UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        return json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def ranks(values):
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / len(valid)
    return out


def bounded_weights(scores):
    # Diversified full investment: 3% floor, approximately 14% ceiling.
    w = np.array([max(0.03, float(scores.get(s, 0.5))) for s in UNIVERSE])
    w /= w.sum()
    for _ in range(20):
        over = w > 0.14
        if not over.any():
            break
        excess = float((w[over] - 0.14).sum())
        w[over] = 0.14
        w[~over] += excess / max(1, int((~over).sum()))
    w = np.maximum(w, 0.03)
    w /= w.sum()
    return {s: float(x) for s, x in zip(UNIVERSE, w)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble or len(ensemble) > 10:
        return
    factor_ids = [f["factor_id"] for f in ensemble]
    series, last_date = {}, None
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=220)
            if df is not None and len(df) >= 65:
                df = df.sort_values("date")
                close = np.asarray(df["close"], dtype=float)
                series[symbol] = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
                last_date = df.iloc[-1]["date"]
        except Exception:
            pass
    if len(series) < 12 or last_date is None:
        return
    try:
        block = int(np.busday_count("2020-01-01", str(last_date)[:10]) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    raw = {f["factor_id"]: {} for f in ensemble}
    for s, r in series.items():
        r10, r20, r30, r40 = r[-11:-1], r[-21:-1], r[-31:-1], r[-41:-1]
        t10, t20, t30, t40 = [float(np.sum(x)) for x in (r10, r20, r30, r40)]
        v10, v20 = max(float(np.std(r10)), .008), max(float(np.std(r20)), .008)
        down = max(float(np.std(r30[r30 < 0])) if np.any(r30 < 0) else float(np.std(r30)), .008)
        vals = {
            "miner_2_downside_adjusted_momentum_30d": t30 / down,
            "miner_3_20300516_momentum_deceleration_reversal_10d": (t10 - t30 / 3.0) / v10,
            "miner_2_20300321_defensive_trend_10d": t20 / v20,
            "miner_3_20300124_trend_agreement_residual_10d": (np.sign(t10) + np.sign(t20) + np.sign(t30)) * t10 / (3.0 * v10),
            "miner_3_20300418_drawdown_rebound_10d": max(0.0, t10) / down if t30 < 0 else 0.0,
            "miner_2_20290628_dispersion_adjusted_recovery_10d": (t10 - float(np.std(r10))) / v10,
            "miner_1_relative_momentum_40d": t40 / max(float(np.std(r40)), .008),
        }
        for f in ensemble:
            raw[f["factor_id"]][s] = vals.get(f["factor_id"], 0.0)

    score = {s: 0.5 for s in UNIVERSE}
    for f in ensemble:
        rr = ranks(raw[f["factor_id"]])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * (rr[s] - 0.5)

    eq = [s for s in ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH"] if s in series]
    bear = bool(eq) and float(np.mean([np.sum(series[s][-21:-1]) for s in eq])) < 0
    if bear:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.12
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"):
            score[s] -= 0.06

    vols = {s: max(float(np.std(r[-21:-1])), .008) for s, r in series.items()}
    mean_vol = float(np.mean(list(vols.values())))
    for s in UNIVERSE:
        score[s] *= 0.90 + 0.10 * mean_vol / vols.get(s, mean_vol)
    target = bounded_weights(score)
    center, spread = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-9)
    forecast_returns = {s: float(0.01 * (score[s] - center) / spread) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10)
"}

