import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        factors = json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])
        return factors[:10] if len(factors) <= 10 else []
    except Exception:
        return []


def rank_map(values):
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / len(valid) if valid else 0.5
    return out


def make_weights(score):
    # Diversified, fully invested long-only portfolio; no cash sleeve.
    w = np.array([max(0.03, float(score.get(s, 0.5))) for s in UNIVERSE])
    w /= w.sum()
    for _ in range(50):
        over = w > 0.14
        if not over.any():
            break
        excess = float(np.sum(w[over] - 0.14))
        w[over] = 0.14
        w[~over] += excess / max(1, int((~over).sum()))
    w = np.maximum(w, 0.03)
    w /= w.sum()
    return {s: float(x) for s, x in zip(UNIVERSE, w)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble:
        return
    factor_ids = [f["factor_id"] for f in ensemble]
    returns, last_date = {}, None
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=220)
            if df is not None and len(df) >= 65:
                df = df.sort_values("date")
                px = np.asarray(df["close"], dtype=float)
                returns[symbol] = px[1:] / np.maximum(px[:-1], 1e-12) - 1.0
                last_date = df.iloc[-1]["date"]
        except Exception:
            pass
    if len(returns) < 12 or last_date is None:
        return
    try:
        block = int(np.busday_count("2020-01-01", str(last_date)[:10]) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    raw = {f["factor_id"]: {} for f in ensemble}
    for symbol, r in returns.items():
        r10, r20, r30, r40 = r[-11:-1], r[-21:-1], r[-31:-1], r[-41:-1]
        t10, t20, t30, t40 = [float(np.sum(x)) for x in (r10, r20, r30, r40)]
        v10, v20, v40 = [max(float(np.std(x)), 0.008) for x in (r10, r20, r40)]
        neg = r30[r30 < 0]
        downside = max(float(np.std(neg)) if len(neg) else float(np.std(r30)), 0.008)
        path = np.cumsum(r30)
        drawdown = float(np.min(path - np.maximum.accumulate(path)))
        values = {
            "miner_3_20300516_momentum_deceleration_reversal_10d": (t10 - t30 / 3.0) / v10,
            "miner_1_20300725_drawdown_rebound_revalidated_10d": max(0.0, t10) / downside if t30 < 0 else 0.0,
            "miner_3_20300404_range_position_reversal_10d": -t10 / v10,
            "miner_2_20300321_defensive_trend_10d": t20 / v20,
            "miner_2_20300627_risk_adjusted_trend_20d": t20 / v20 + drawdown / v20,
            "miner_1_relative_momentum_40d": t40 / v40,
            "miner_2_downside_adjusted_momentum_30d": t30 / downside,
        }
        for f in ensemble:
            raw[f["factor_id"]][symbol] = values.get(f["factor_id"], 0.0)

    score = {s: 0.5 for s in UNIVERSE}
    for f in ensemble:
        ranks = rank_map(raw[f["factor_id"]])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * (ranks[s] - 0.5)

    equity = [s for s in ("000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH") if s in returns]
    bear = equity and float(np.mean([np.sum(returns[s][-21:-1]) for s in equity])) < 0
    if bear:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.12
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"):
            score[s] -= 0.06

    vols = {s: max(float(np.std(r[-21:-1])), 0.008) for s, r in returns.items()}
    avg_vol = float(np.mean(list(vols.values())))
    for s in UNIVERSE:
        score[s] *= 0.90 + 0.10 * avg_vol / vols.get(s, avg_vol)
    target = make_weights(score)
    mean_score = float(np.mean(list(score.values())))
    sd_score = max(float(np.std(list(score.values()))), 1e-9)
    forecast_returns = {s: float(0.01 * (score[s] - mean_score) / sd_score) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10)

