        values = {
            "miner_3_20300516_momentum_deceleration_reversal_10d": (r10 - r30 / 3.0) / v10,
            "miner_2_20270617_downside_adjusted_momentum_30d": r30 / downside,
            "miner_2_20300321_defensive_trend_10d": r20 / v20,
            "miner_1_20270422_relative_momentum_40d": r40 / v40,
