def load_ensemble():
    try:
        fs = json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []


def rank_cs(vals):
    good = sorted((s, v) for s, v in vals.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / n
    return out


def make_weights(scores):
    # Small-universe diversification: 3% floor, 14% cap, and no cash sleeve.
    w = np.array([max(0.03, float(scores[s])) for s in UNIVERSE])
    w /= w.sum()
    for _ in range(20):
        over = w > 0.14
        if not np.any(over):
            break
