        abs10 = max(float(np.sum(np.abs(r[-11:-1]))), 1e-8)
        abs40 = max(float(np.sum(np.abs(r[-41:-1]))), 1e-8)
        eff_spread = r10 / abs10 - r40 / abs40
        # Close-only range position proxy, lagged by one observation.
        window = r[-41:-1]
        levels = np.cumprod(np.r_[1.0, 1.0 + window])
        range_rev = -(levels[-1] - np.min(levels)) / max(np.max(levels) - np.min(levels), 1e-8)
        # Rebound rewards recovery from a trailing drawdown, but is capped by volatility.
        peak = np.maximum.accumulate(levels)
        trough = np.min(levels[-21:])
        rebound = (levels[-1] / max(trough, 1e-8) - 1.0) / v10
        vals = {
            "miner_2_downside_adjusted_momentum_30d": r30 / down,
            "miner_3_20300516_momentum_deceleration_reversal_10d": (r10 - r30 / 3.0) / v10,
            "miner_2_20300321_defensive_trend_10d": r30 / v30,
            "miner_2_20301003_inefficiency_spread_reversal_20d": -eff_spread / v20,
            "miner_3_20300404_range_position_reversal_10d": range_rev,
            "miner_3_20301003_efficiency_trend_contrarian_10d": -(r20 / abs40) / v20,
            "miner_1_20300725_drawdown_rebound_revalidated_10d": rebound,
            "miner_1_relative_momentum_40d": r40 / v40,
            "miner_1_20301017_relative_reversal": 0.0,  # filled cross-sectionally below
        }
        for fid in raw:
            raw[fid][symbol] = vals.get(fid, 0.0)

    # Relative reversal is negative relative 20-day return, volatility scaled.
    universe_r20 = np.mean([retv for retv in [float(np.sum(r[-21:-1])) for r in data.values()]])
    for s, r in data.items():
        raw["miner_1_20301017_relative_reversal"][s] = -(ret(20) - universe_r20) / max(float(np.std(r[-21:-1])), .008)

    score = {s: 0.5 for s in UNIVERSE}
    for f in ensemble:
        ranks = rank_cs(raw[f["factor_id"]])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * (ranks[s] - .5)

