        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"): score[s] -= .05

    vol = {s: max(float(np.std(r[-21:-1])), .008) for s, r in data.items()}
    av = float(np.mean(list(vol.values())))
    for s in UNIVERSE:
        score[s] *= .92 + .08 * av / vol.get(s, av)
