UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        factors = json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])
        return factors if 0 < len(factors) <= 10 else []
    except Exception:
        return []


def cs_rank(values):
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    result = {s: 0.5 for s in UNIVERSE}
    if not valid:
        return result
    n = len(valid)
    for i, (s, _) in enumerate(valid):
        result[s] = (i + 1.0) / n
    return result


def bounded_weights(score):
    # Full investment, diversified across the deliberately small 15-asset universe.
    w = np.array([max(0.03, float(score[s])) for s in UNIVERSE], dtype=float)
    w /= w.sum()
    for _ in range(50):
        high = w > 0.14
        if not high.any():
            break
        excess = float(np.sum(w[high] - 0.14))
        w[high] = 0.14
        w[~high] += excess / max(1, int((~high).sum()))
    w = np.maximum(w, 0.03)
    w /= w.sum()
    return {s: float(x) for s, x in zip(UNIVERSE, w)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble:
        return
    factor_ids = [f["factor_id"] for f in ensemble]
    data, last_date = {}, None
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=220)
            if df is not None and len(df) >= 65:
                df = df.sort_values("date")
                close = np.asarray(df["close"], dtype=float)
                data[symbol] = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
                last_date = df.iloc[-1]["date"]
        except Exception:
            continue
    if len(data) < 12 or last_date is None:
        return
    try:
        block = int(np.busday_count("2020-01-01", str(last_date)[:10]) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    raw = {f["factor_id"]: {} for f in ensemble}
    for symbol, r in data.items():
        def ret(n):
            return float(np.sum(r[-n-1:-1]))
        r10, r20, r30, r40 = ret(10), ret(20), ret(30), ret(40)
        v10 = max(float(np.std(r[-11:-1])), 0.008)
        v20 = max(float(np.std(r[-21:-1])), 0.008)
        v30 = max(float(np.std(r[-31:-1])), 0.008)
        v40 = max(float(np.std(r[-41:-1])), 0.008)
        recent = r[-31:-1]
        downside = max(float(np.std(recent[recent < 0])) if np.any(recent < 0) else v30, 0.008)
        path = max(float(np.sum(np.abs(r[-41:-1]))), 1e-8)
        # These compact proxies preserve the admitted factor directions and horizons.
        values = {
            "miner_3_20300516_momentum_deceleration_reversal_10d": (r10 - r30 / 3.0) / v10,
            "miner_2_20270617_downside_adjusted_momentum_30d": r30 / downside,
            "miner_2_20300321_defensive_trend_10d": r20 / v20,
            "miner_1_20270422_relative_momentum_40d": r40 / v40,
            "miner_2_20300627_risk_adjusted_trend_20d": r20 / v20,
            "miner_1_20300725_drawdown_rebound_revalidated_10d": max(0.0, r10) / downside if r30 < 0 else 0.0,
            "miner_3_20300404_range_position_reversal_10d": -r10 / v10,
            "miner_2_20301003_inefficiency_spread_reversal_20d": -(r40 / path) / v30,
            "miner_3_20301003_efficiency_trend_contrarian_10d": -(r20 / path) / v20,
        }
        for factor in factor_ids:
            raw[factor][symbol] = values.get(factor, 0.0)

    score = {s: 0.5 for s in UNIVERSE}
    for factor in ensemble:
        ranked = cs_rank(raw[factor["factor_id"]])
        for symbol in UNIVERSE:
            score[symbol] += factor["weight"] * factor.get("direction", 1) * (ranked[symbol] - 0.5)

    # Bearish/corrective regime: remain fully invested but rotate toward tradable defensives.
    equity = [s for s in ("000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH") if s in data]
    equity_return = np.mean([np.sum(data[s][-21:-1]) for s in equity]) if equity else 0.0
    if equity_return < 0:
        for symbol in ("XAU", "US10Y", "CN10Y"):
            score[symbol] += 0.12
        for symbol in ("BTC", "ETH", "SOX", "NDX", "WTI"):
            score[symbol] -= 0.06

    vols = {s: max(float(np.std(r[-21:-1])), 0.008) for s, r in data.items()}
    average_vol = float(np.mean(list(vols.values())))
    for symbol in UNIVERSE:
        score[symbol] *= 0.9 + 0.1 * average_vol / vols.get(symbol, average_vol)
    target = bounded_weights(score)
    mean_score = float(np.mean(list(score.values())))
    sd_score = max(float(np.std(list(score.values()))), 1e-9)
