UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        fs = json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []


def cs_rank(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if not valid:
        return out
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / len(valid)
    return out


def bounded_weights(scores):
    # 15-name, fully invested, diversified long-only portfolio.
    w = np.array([max(0.03, float(scores[s])) for s in UNIVERSE], dtype=float)
    w /= w.sum()
    for _ in range(30):
        high = w > 0.14
        if not high.any():
            break
        excess = float((w[high] - 0.14).sum())
        w[high] = 0.14
        w[~high] += excess / max(1, int((~high).sum()))
    w = np.maximum(w, 0.03)
    w /= w.sum()
    return {s: float(x) for s, x in zip(UNIVERSE, w)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble:
        return
    factor_ids = [f["factor_id"] for f in ensemble]
    data = {}
    last_date = None
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=220)
            if df is not None and len(df) >= 70:
                df = df.sort_values("date")
                c = np.asarray(df["close"], dtype=float)
                r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
                data[symbol] = r
                last_date = df.iloc[-1]["date"]
        except Exception:
            pass
    if len(data) < 12 or last_date is None:
        return
    try:
        block = int(np.busday_count("2020-01-01", str(last_date)[:10]) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    # All expressions use the last completed observation only (the final return
    # is excluded), then are rank-normalized before ensemble aggregation.
    raw = {f["factor_id"]: {} for f in ensemble}
    for s, full_r in data.items():
        r = full_r[:-1]
        def ret(n): return float(np.sum(r[-n:]))
        r10, r20, r30, r40 = ret(10), ret(20), ret(30), ret(40)
        v10 = max(float(np.std(r[-10:])), .008)
        v20 = max(float(np.std(r[-20:])), .008)
        v60 = max(float(np.std(r[-60:])), .008)
        down30 = max(float(np.sqrt(np.mean(np.minimum(r[-30:], 0.0) ** 2))), .008)
        abs10, abs40 = max(float(np.sum(np.abs(r[-10:]))), 1e-8), max(float(np.sum(np.abs(r[-40:]))), 1e-8)
        eff = r10 / abs10 - r40 / abs40
        # Close-level 60-session range proxy, matching the reversal intent.
        lev = np.cumprod(1.0 + r[-60:])
        rp = -(((lev[-1] - lev.min()) / max(lev.max() - lev.min(), 1e-8) - .5) * 2.0 + r20 / (np.sqrt(20) * v20)) / 2.0
        vals = {
            "miner_3_20301031_vol_adjusted_acceleration_10d": (ret(5) / v20) - (r20 / v60),
            "miner_2_20270617_downside_adjusted_momentum_30d": r30 / (down30 * np.sqrt(252)),
            "miner_2_20301031_volscaled_reversal_20d": -r20 / (v20 * np.sqrt(20)),
            "miner_2_20301003_inefficiency_spread_reversal_20d": -eff,
            "miner_3_20300404_range_position_reversal_10d": rp,
            "miner_3_20301003_efficiency_trend_contrarian_10d": -(r40 / abs40) / v20,
            "miner_1_relative_momentum_40d": r40,
        }
        for f in ensemble:
            raw[f["factor_id"]][s] = vals.get(f["factor_id"], 0.0)

    score = {s: 0.5 for s in UNIVERSE}
    for f in ensemble:
        ranks = cs_rank(raw[f["factor_id"]])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * (ranks[s] - .5)

    # Bullish recovery: participate broadly, but inverse-vol scale limits
    # crypto/commodity shock risk without introducing a cash sleeve.
    vols = {s: max(float(np.std(data[s][:-1][-20:])), .008) for s in data}
    av = float(np.mean(list(vols.values())))
    for s in UNIVERSE:
        score[s] *= .90 + .10 * av / vols.get(s, av)
    target = bounded_weights(score)
    mean, std = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-8)
    forecast_returns = {s: float(.01 * (score[s] - mean) / std) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10)
"}

