import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        fs = json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []


def ranks(x):
    good = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if good:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def bounded_weights(score):
    # Broad participation is appropriate for a 15-asset, bullish-but-risky regime.
    w = np.array([0.03 + 0.97 * max(0.0, score.get(s, 0.5)) for s in UNIVERSE], dtype=float)
    w /= w.sum()
    # Project excess above 14% onto assets below the cap.
    for _ in range(30):
        over = w > 0.14 + 1e-12
        if not over.any(): break
        excess = float((w[over] - 0.14).sum())
        w[over] = 0.14
        under = ~over
        w[under] += excess / max(1, int(under.sum()))
    w = np.maximum(w, 0.03)
    w /= w.sum()
    return {s: float(v) for s, v in zip(UNIVERSE, w)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble:
        return
    factor_ids = [f["factor_id"] for f in ensemble]
    returns = {}
    last_date = None
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=240)
            if df is not None and len(df) >= 75:
                df = df.sort_values("date")
                p = np.asarray(df["close"], dtype=float)
                returns[symbol] = p[1:] / np.maximum(p[:-1], 1e-12) - 1.0
                last_date = df.iloc[-1]["date"]
        except Exception:
            pass
    if len(returns) < 12 or last_date is None:
        return
    try:
        block = int(np.busday_count("2020-01-01", str(last_date)[:10]) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    raw = {f["factor_id"]: {} for f in ensemble}
    for s, allr in returns.items():
        r = allr[:-1]  # lag: do not use the still-forming/latest observation
        def ret(n): return float(np.sum(r[-n:]))
        r5, r10, r20, r30, r40 = ret(5), ret(10), ret(20), ret(30), ret(40)
        v20 = max(float(np.std(r[-20:])), 0.008)
        v60 = max(float(np.std(r[-60:])), 0.008)
        down20 = max(float(np.sqrt(np.mean(np.minimum(r[-20:], 0.0)**2))), 0.008)
        down30 = max(float(np.sqrt(np.mean(np.minimum(r[-30:], 0.0)**2))), 0.008)
        abs10, abs40 = max(float(np.abs(r[-10:]).sum()), 1e-8), max(float(np.abs(r[-40:]).sum()), 1e-8)
        efficiency = r40 / abs40
        path = np.cumprod(1.0 + r[-60:])
        lo, hi = float(path.min()), float(path.max())
        range_reversal = -2.0 * ((float(path[-1]) - lo) / max(hi-lo, 1e-8) - .5)
        vals = {
            "miner_3_risk_scaled_trend_contrarian_20d": -r20 / v20,
            "miner_2_20270617_downside_adjusted_momentum_30d": r30 / (down30 * np.sqrt(252)),
            "miner_3_20301031_vol_adjusted_acceleration_10d": r5 / v20 - r20 / v60,
            "miner_2_20301128_long_downside_vol_reversal_20d": -r20 / (down20 * np.sqrt(20)),
            "miner_3_20300516_momentum_deceleration_reversal_10d": -(r10 - r30 / 3.0) / v20,
            "miner_2_20301003_inefficiency_spread_reversal_20d": -(r10 / max(float(np.abs(r[-10:]).sum()), 1e-8) - efficiency),
            "miner_3_20300404_range_position_reversal_10d": range_reversal - r10 / (v20 * np.sqrt(10)),
            "miner_3_20301003_efficiency_trend_contrarian_10d": -efficiency / v20,
        }
        for f in ensemble:
            raw[f["factor_id"]][s] = float(vals.get(f["factor_id"], 0.0))

    score = {s: 0.5 for s in UNIVERSE}
    for f in ensemble:
        rr = ranks(raw[f["factor_id"]])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * (rr[s] - 0.5)
    # Medium-high volatility: modest inverse-volatility overlay, not a cash sleeve.
    vol = {s: max(float(np.std(returns[s][:-1][-20:])), 0.008) for s in returns}
    av = float(np.mean(list(vol.values())))
    for s in UNIVERSE:
        score[s] *= 0.90 + 0.10 * av / vol.get(s, av)
    target = bounded_weights(score)
    mu, sig = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-8)
    forecast_returns = {s: float(0.01 * (score[s] - mu) / sig) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast_returns, factor_ids=factor_ids, horizon_days=10)

