import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE_PATH = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None

def load_ensemble():
    try:
        fs = json.loads(ENSEMBLE_PATH.read_text()).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []

def cross_rank(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if valid:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.0) / len(valid)
    return out

def bounded_weights(score):
    # A complete, diversified, long-only portfolio; no cash sleeve.
    w = np.array([0.03 + 0.97 * max(0.0, score.get(s, 0.5)) for s in UNIVERSE], dtype=float)
    w /= w.sum()
    for _ in range(40):
        over = w > 0.14
        if not over.any(): break
        excess = float(np.sum(w[over] - 0.14)); w[over] = 0.14
        w[~over] += excess / max(1, int((~over).sum()))
    w = np.maximum(w, 0.03); w /= w.sum()
    return {s: float(v) for s, v in zip(UNIVERSE, w)}

@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble: return
    factor_ids = [f["factor_id"] for f in ensemble]
    prices, last_date = {}, None
    for s in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=s, days=240)
            if df is not None and len(df) >= 80:
                df = df.sort_values("date")
                prices[s] = np.asarray(df["close"], dtype=float)
                last_date = df.iloc[-1]["date"]
        except Exception: pass
    if len(prices) < 12 or last_date is None: return
    try: block = int(np.busday_count("2020-01-01", str(last_date)[:10]) // 10)
    except Exception: return
    if block == LAST_BLOCK: return
    LAST_BLOCK = block
    raw = {f["factor_id"]: {} for f in ensemble}; rets = {}
    for s, p in prices.items():
        # p[-1] is excluded: decisions use only the previous completed session.
        r = p[:-1][1:] / np.maximum(p[:-1][:-1], 1e-12) - 1.0
        if len(r) < 60: continue
        rets[s] = r
        def cum(n): return float(np.prod(1.0 + r[-n:]) - 1.0)
        r5,r10,r20,r30,r40,r60 = [cum(n) for n in (5,10,20,30,40,60)]
        v10=max(float(np.std(r[-10:])),.008); v20=max(float(np.std(r[-20:])),.008)
        v40=max(float(np.std(r[-40:])),.008); v60=max(float(np.std(r[-60:])),.008)
        down30=max(float(np.sqrt(np.mean(np.minimum(r[-30:],0)**2))),.008)
        down40=max(float(np.sqrt(np.mean(np.minimum(r[-40:],0)**2))),.008)
        eff10=r10/max(float(np.abs(r[-10:]).sum()),1e-8)
        eff40=r40/max(float(np.abs(r[-40:]).sum()),1e-8)
        # Factor definitions are deliberately simple and lagged; ranks provide robustness.
        vals = {
          "miner_1_20301031_vol_adjusted_acceleration": r5/v20-r20/v60,
          "miner_2_downside_adjusted_momentum_30d": r30/(down30*np.sqrt(30.0)),
          "miner_1_relative_momentum_40d": r40,
          "miner_2_20300321_defensive_trend_10d": r10/v10,
          "miner_3_risk_scaled_trend_contrarian_20d": -r20/(v60*np.sqrt(20.0)),
          "miner_2_20301226_vol_contraction_reversal_20d": -r20*(v40/v10),
          "miner_2_20301128_long_downside_vol_reversal_20d": -r20/(down40*np.sqrt(20.0)),
          "miner_3_20300516_momentum_deceleration_reversal_10d": (r60/3.0-r20)/(v20*np.sqrt(252.0)),
          "miner_3_20301003_efficiency_trend_contrarian_10d": -(r40/(v20*np.sqrt(20.0))) * np.clip(abs(r40)/max(float(np.abs(r[-40:]).sum()),1e-8),0,1),
        }
        for f in ensemble: raw[f["factor_id"]][s] = float(vals[f["factor_id"]])
    score={s:0.5 for s in UNIVERSE}
    for f in ensemble:
        z=cross_rank(raw[f["factor_id"]])
        for s in UNIVERSE: score[s] += float(f["weight"])*int(f.get("direction",1))*(z[s]-.5)
    vols={s:max(float(np.std(rets[s][-20:])),.008) for s in rets}; av=float(np.mean(list(vols.values())))
    # Mild inverse-volatility tilt avoids making the correction a crypto concentration bet.
    for s in UNIVERSE: score[s] *= .90 + .10*av/vols.get(s,av)
    target=bounded_weights(score)
    mu=float(np.mean(list(score.values()))); sd=max(float(np.std(list(score.values()))),1e-8)
    forecast={s:float(.01*(score[s]-mu)/sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

