        }
        vols[symbol] = v20
        for f in fs:
            raw[f["factor_id"]][symbol] = vals[f["factor_id"]]

    score = {s: 0.5 for s in UNIVERSE}
    for f in fs:
        ranked = cross_rank(raw[f["factor_id"]])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * (ranked[s] - 0.5)
    avgvol = float(np.mean(list(vols.values()))) if vols else 0.01
    for s in UNIVERSE:
        score[s] *= 0.90 + 0.10 * avgvol / vols.get(s, avgvol)
    target = bounded_weights(score)
    mu = float(np.mean(list(score.values())))
    sd = max(float(np.std(list(score.values()))), 1e-8)
    forecast = {s: float(0.01 * (score[s] - mu) / sd) for s in UNIVERSE}
