import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Screener ensemble is authoritative; support both the shared root and legacy factor path.
ENSEMBLE_PATHS = [Path(__file__).parent / "factor_ensemble.json", Path(__file__).parent / "factors" / "factor_ensemble.json"]
LAST_BLOCK = None

def load_ensemble():
    for path in ENSEMBLE_PATHS:
        try:
            fs = json.loads(path.read_text()).get("selected_factors", [])
            if 0 < len(fs) <= 10:
                return fs
        except Exception:
            pass
    return []

def rank(values):
    out = {s: .5 for s in UNIVERSE}
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out

def bounded_weights(score):
    # Smooth score allocation, then a deterministic capped simplex projection.
    x = np.array([max(score.get(s, .5), 0.0) + .05 for s in UNIVERSE], float)
    x /= x.sum()
    for _ in range(100):
        low, high = x < .03, x > .14
        if not (low.any() or high.any()):
            break
        fixed = low | high
        x[low], x[high] = .03, .14
        free = ~fixed
        if free.any():
            remainder = 1.0 - x[fixed].sum()
            x[free] *= remainder / max(x[free].sum(), 1e-12)
    # Numerical cleanup while preserving all contractual bounds.
    x = np.clip(x, .03, .14)
    for _ in range(20):
        d = 1.0 - x.sum()
        if abs(d) < 1e-12: break
        eligible = x < .14 - 1e-10 if d > 0 else x > .03 + 1e-10
        if not eligible.any(): break
        x[eligible] += d / eligible.sum()
        x = np.clip(x, .03, .14)
    x /= x.sum()
    return {s: float(w) for s, w in zip(UNIVERSE, x)}

@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    factors = load_ensemble()
    if not factors:
        return
    factor_ids = [f["factor_id"] for f in factors]
    px, vols = {}, {}
    last = None
    for s in UNIVERSE:
        try:
            d = get_stock_daily_data(symbol=s, days=240)
            if d is not None and len(d) >= 80:
                d = d.sort_values("date")
                px[s] = np.asarray(d["close"], float)
                last = d.iloc[-1]["date"]
        except Exception:
            pass
    if len(px) < 12 or last is None:
        return
    vix = 1.0
    try:
        d = get_index_daily_data(symbol="VIX", days=160)
        if d is not None and len(d) >= 30:
            z = np.asarray(d.sort_values("date")["close"], float)
            vix = float(np.clip(z[-1] / max(np.median(z[-120:]), 1e-8), .5, 2.0))
    except Exception:
        pass
    try:
        block = int(np.busday_count("2020-01-01", str(last)[:10]) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block
    raw = {f["factor_id"]: {} for f in factors}
    for s, p in px.items():
        r = p[1:] / np.maximum(p[:-1], 1e-12) - 1.0
        def ret(n): return float(np.prod(1.0 + r[-n:]) - 1.0)
        r5, r10, r20, r30, r40, r60 = [ret(n) for n in (5, 10, 20, 30, 40, 60)]
        v10, v20, v40 = [max(float(np.std(r[-n:])), .008) for n in (10, 20, 40)]
        neg = r[-40:][r[-40:] < 0]
        down = max(float(np.std(neg)) if len(neg) >= 5 else v40, .008)
        prior = p[-21:-1]
        range_signal = -(p[-1] - np.max(prior)) / max(np.max(prior) - np.min(prior), 1e-12) + .35 * r60
        vals = {
          "miner_3_20310515_risk_scaled_relative_deceleration_20d": (r60 / 3.0 - r20) / v40,
          "miner_2_downside_adjusted_momentum_30d": r30 / (v40 + down),
          "miner_3_20310501_vix_regime_reversal_20d": -r20 * vix / (v40 + 1e-12),
          "miner_3_20310320_downside_risk_reversal_20d": -r20 / (v40 + down),
          "miner_1_range_momentum_blend_20d": range_signal,
          "miner_3_20301031_vol_adjusted_acceleration_10d": (r10 - r20 / 2.0) / v10,
          "miner_1_20270422_relative_momentum_40d": r40 / (v40 + 1e-12),
        }
        vols[s] = v20
        for f in raw:
            raw[f][s] = vals.get(f, 0.0)
    score = {s: .5 for s in UNIVERSE}
    for f in factors:
        rr = rank(raw[f["factor_id"]])
        for s in UNIVERSE:
            score[s] += f["weight"] * f.get("direction", 1) * (rr[s] - .5)
    av = np.mean(list(vols.values()))
    for s in UNIVERSE:
        score[s] *= .92 + .08 * av / max(vols.get(s, av), 1e-8)
    target = bounded_weights(score)
    mean, st = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01 * (score[s] - mean) / st) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)

