from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None

def load_ensemble():
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []

def rank(values):
    out = {s: 0.5 for s in UNIVERSE}
    a = sorted((s, x) for s, x in values.items() if np.isfinite(x))
    for i, (s, _) in enumerate(a):
        out[s] = (i + 1.0) / len(a)
    return out

def bounded_weights(score):
    # High-risk bullish regime: broad, fully invested, inverse-volatility tilted.
    x = np.array([max(score.get(s, 0.5), 0.0) + 0.05 for s in UNIVERSE])
    x /= x.sum()
    for _ in range(60):
        hi, lo = x > 0.14, x < 0.03
        fixed = hi | lo
        if not fixed.any():
            break
        x[hi], x[lo] = 0.14, 0.03
        free = ~fixed
        if free.any():
            x[free] *= (1.0 - x[fixed].sum()) / max(x[free].sum(), 1e-12)
    x = np.clip(x, 0.03, 0.14)
    x /= x.sum()
    return {s: float(x[i]) for i, s in enumerate(UNIVERSE)}

@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    fs = load_ensemble()
    if not fs:
        return
    ids = [f["factor_id"] for f in fs]
    px, vols = {}, {}
    latest = None
    for s in UNIVERSE:
        try:
            d = get_stock_daily_data(symbol=s, days=240)
            if d is not None and len(d) >= 80:
                d = d.sort_values("date")
                p = np.asarray(d["close"], float)
                if np.all(np.isfinite(p)) and np.all(p > 0):
                    px[s] = p
                    latest = d.iloc[-1]["date"]
        except Exception:
            pass
    if len(px) < 12 or latest is None:
        return
    try:
        block = int(np.busday_count("2020-01-01", str(latest)[:10]) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    vix_ratio = 1.0
    try:
        vd = get_index_daily_data(symbol="VIX", days=160)
        if vd is not None and len(vd) >= 30:
            z = np.asarray(vd.sort_values("date")["close"], float)
            vix_ratio = float(np.clip(z[-1] / max(np.median(z[-120:]), 1e-8), 0.5, 2.0))
    except Exception:
        pass

    raw = {f["factor_id"]: {} for f in fs}
    for s, p in px.items():
        r = p[1:] / np.maximum(p[:-1], 1e-12) - 1.0
        def ret(n): return float(np.prod(1.0 + r[-n:]) - 1.0)
        r10, r20, r30, r40, r60 = [ret(n) for n in (10, 20, 30, 40, 60)]
        v10, v20, v40 = [max(float(np.std(r[-n:])), 0.008) for n in (10, 20, 40)]
        neg = r[-40:][r[-40:] < 0]
        down = max(float(np.std(neg)) if len(neg) >= 5 else v40, 0.008)
        prior = p[-21:-1]
        rng = max(np.max(prior) - np.min(prior), 1e-12)
        # Relative residual reversal: reverse the asset's recent return
        # relative to the equal-weight cross-section, volatility scaled.
        vals = {u: (px[u][-20] / px[u][-1] - 1.0) for u in px}
        rel20 = (p[-1] / p[-21] - 1.0) - np.mean([px[u][-1] / px[u][-21] - 1.0 for u in px])
        allvals = {
            "miner_3_20310515_risk_scaled_relative_deceleration_20d": (r60 / 3.0 - r20) / v40,
            "miner_2_20270617_downside_adjusted_momentum_30d": r30 / (v40 + down),
            "miner_3_20301031_vol_adjusted_acceleration_10d": (r10 - r20 / 2.0) / v10,
            "miner_2_20310904_relative_residual_reversal_20d": -rel20 / v20,
            "miner_3_20310501_vix_regime_reversal_20d": -r20 * vix_ratio / v40,
            "miner_3_20310320_downside_risk_reversal_20d": -r20 / (v40 + down),
            "miner_1_20310417_range_momentum_blend_20d": -(p[-1] - np.max(prior)) / rng + 0.35 * r60,
            "miner_1_20310529_risk_adjusted_multihorizon_reversal_20d": -(0.45 * r10 + 0.35 * r20 + 0.20 * r40) / (v40 + down),
        }
        vols[s] = v20
        for f in ids:
            raw[f][s] = allvals.get(f, 0.0)

    score = {s: 0.5 for s in UNIVERSE}
    for f in fs:
        rr = rank(raw[f["factor_id"]])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * (rr[s] - 0.5)
    avgvol = np.mean(list(vols.values()))
    for s in UNIVERSE:
