import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None

def load_ensemble():
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []

def xrank(d):
    out = {s: 0.5 for s in UNIVERSE}
    a = sorted((s, v) for s, v in d.items() if np.isfinite(v))
    if not a: return out
    for i, (s, _) in enumerate(a): out[s] = (i + 1.0) / len(a)
    return out

def bounded(score):
    x = np.array([max(score.get(s, .5), 0.01) for s in UNIVERSE], float)
    x /= x.sum()
    # Broad exposure is intentional: high-risk bullish regime, no cash sleeve.
    for _ in range(20):
        low, high = x < .03, x > .14
        if not (low.any() or high.any()): break
        fixed = low | high
        x[low], x[high] = .03, .14
        free = ~fixed
        if free.any(): x[free] *= (1.0 - x[fixed].sum()) / max(x[free].sum(), 1e-12)
    x = np.clip(x, .03, .14); x /= x.sum()
    return {s: float(x[i]) for i, s in enumerate(UNIVERSE)}

@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    fs = load_ensemble()
    if not fs: return
    ids = [str(f["factor_id"]) for f in fs]
    prices, vols = {}, {}
    latest = None
    for s in UNIVERSE:
        try:
            d = get_stock_daily_data(symbol=s, days=240)
            if d is None or len(d) < 80: continue
            d = d.sort_values("date")
            p = np.asarray(d["close"], float)
            if np.all(np.isfinite(p)) and np.all(p > 0):
                prices[s] = p; latest = d.iloc[-1]["date"]
        except Exception: pass
    if len(prices) < 12 or latest is None: return
    try: block = int(np.busday_count("2020-01-01", str(latest)[:10]) // 10)
    except Exception: return
    if block == LAST_BLOCK: return
    LAST_BLOCK = block
    vix_ratio = 1.0
    try:
        vd = get_index_daily_data(symbol="VIX", days=160)
        if vd is not None and len(vd) >= 30:
            z = np.asarray(vd.sort_values("date")["close"], float)
            vix_ratio = float(np.clip(z[-1] / max(np.median(z[-120:]), 1e-8), .5, 2.0))
    except Exception: pass
    cross20 = np.mean([prices[u][-1] / prices[u][-21] - 1 for u in prices])
    raw = {f: {} for f in ids}
    for s, p in prices.items():
        r = p[1:] / np.maximum(p[:-1], 1e-12) - 1
        def ret(n): return float(np.prod(1 + r[-n:]) - 1)
        r10, r20, r30, r40, r60 = [ret(n) for n in (10,20,30,40,60)]
        v10, v20, v40 = [max(float(np.std(r[-n:])), .008) for n in (10,20,40)]
        neg = r[-40:][r[-40:] < 0]
        down = max(float(np.std(neg)) if len(neg) >= 5 else v40, .008)
        prior = p[-21:-1]; rng = max(np.max(prior)-np.min(prior), 1e-12)
        rel = r20 - cross20
        vals = {
          "deceleration": (r60/3-r20)/v40,
          "downside_risk_reversal": -r20/(v40+down),
          "vix_regime_reversal": -r20*vix_ratio/v40,
          "vol_adjusted_acceleration": (r10-r20/2)/v10,
          "downside_adjusted_momentum": r30/(v40+down),
          "multihorizon_reversal": -(0.45*r10+0.35*r20+0.20*r40)/(v40+down),
          "range_momentum_blend": -(p[-1]-np.max(prior))/rng + .35*r60,
          "residual_reversal": -rel/v20,
        }
        vols[s] = v20
        for f in ids:
            key = next((k for k in vals if k in f), None)
            raw[f][s] = vals.get(key, 0.0)
    score = {s: .5 for s in UNIVERSE}
    for f in fs:
        rr = xrank(raw[f["factor_id"]])
        for s in UNIVERSE: score[s] += float(f["weight"]) * int(f.get("direction",1)) * (rr[s]-.5)
    av = float(np.mean(list(vols.values())))
    for s in UNIVERSE: score[s] *= .92 + .08*av/max(vols.get(s,av), 1e-8)
    target = bounded(score)
    mean = float(np.mean(list(score.values()))); sd = max(float(np.std(list(score.values()))), 1e-8)
    forecast = {s: float(.01*(score[s]-mean)/sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)

