def load_factors():
    try:
        selected = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])
        return selected if 0 < len(selected) <= 10 else []
    except Exception:
        return []


def cross_rank(values):
    result = {s: 0.5 for s in UNIVERSE}
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    if valid:
        for i, (s, _) in enumerate(valid):
            result[s] = (i + 1.0) / len(valid)
    return result


def make_weights(scores):
    # Full investment, long-only, diversified across the small 15-asset universe.
    w = np.array([max(float(scores.get(s, 0.5)), 1e-10) for s in UNIVERSE])
    w /= w.sum()
    for _ in range(100):
        low, high = w < 0.03, w > 0.14
        if not (low.any() or high.any()):
            break
        fixed = low | high
        w[low], w[high] = 0.03, 0.14
        free = ~fixed
        if free.any():
            w[free] *= (1.0 - w[fixed].sum()) / w[free].sum()
    w = np.maximum(w, 0.03)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
