import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_factors():
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []


def rank_values(values):
    out = {s: 0.5 for s in UNIVERSE}
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    if valid:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.0) / len(valid)
    return out


def project_weights(scores):
    # Full-investment long-only box: all 15 assets remain represented.
    w = np.array([max(float(scores.get(s, 0.5)), 1e-8) for s in UNIVERSE])
    w /= w.sum()
    for _ in range(30):
        low, high = w < 0.03, w > 0.14
        if not (low.any() or high.any()):
            break
        fixed = low | high
        w[low], w[high] = 0.03, 0.14
        free = ~fixed
        if free.any():
            w[free] *= (1.0 - w[fixed].sum()) / w[free].sum()
    w = np.clip(w, 0.03, 0.14)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    factors = load_factors()
    if not factors:
        return
    factor_ids = [str(f["factor_id"]) for f in factors]
    prices = {}
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=240)
            if df is not None and len(df) >= 80:
                p = np.asarray(df.sort_values("date")["close"], dtype=float)
                if np.all(np.isfinite(p)) and np.all(p > 0):
                    prices[symbol] = p
        except Exception:
            pass
    if len(prices) < 12:
        return
    try:
        sample = get_stock_daily_data(symbol=next(iter(prices)), days=2)
        date = str(sample.sort_values("date").iloc[-1]["date"])[:10]
        block = int(np.busday_count("2020-01-01", date) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    returns = {s: p[1:] / p[:-1] - 1.0 for s, p in prices.items()}
    common = min(len(x) for x in returns.values())
    market = np.mean([x[-min(60, common):] for x in returns.values()], axis=0)
    try:
        vix = get_index_daily_data(symbol="VIX", days=160)
        vp = np.asarray(vix.sort_values("date")["close"], dtype=float)
        vix_ratio = float(np.clip(vp[-1] / max(np.median(vp[-120:]), 1e-8), 0.5, 2.0))
    except Exception:
        vix_ratio = 1.0

    raw = {str(f["factor_id"]): {} for f in factors}
    inverse_vol = {}
    for symbol, r in returns.items():
        def cumulative(n):
            return float(np.prod(1.0 + r[-n:]) - 1.0)
        r10, r20, r30, r40, r60 = [cumulative(n) for n in (10, 20, 30, 40, 60)]
        v20, v40 = max(np.std(r[-20:]), 0.008), max(np.std(r[-40:]), 0.008)
        negative = r[-40:][r[-40:] < 0]
        downside = max(np.std(negative) if len(negative) >= 5 else v40, 0.008)
        inverse_vol[symbol] = 1.0 / v20
        market20 = float(np.prod(1.0 + market[-20:]) - 1.0)
        beta = float(np.cov(r[-60:], market[-60:])[0, 1] / max(np.var(market[-60:]), 1e-8))
        values = {
            "downside_adjusted_momentum": r30 / downside,
            "relative_momentum": r40 / v40,
            "range_momentum_blend": 0.5 * r10 / v20 + 0.5 * r20 / v40,
            "risk_scaled_relative_deceleration": (r60 / 3.0 - r20) / v40,
            "vix_regime_reversal": -r20 * vix_ratio / v40,
            "risk_scaled_trend_contrarian": -r20 / v20,
            "residual_trend": (r20 - beta * market20) / v40,
        }
        for f in factors:
            fid = str(f["factor_id"])
            key = next((k for k in values if k in fid), None)
            raw[fid][symbol] = values.get(key, 0.0) * int(f.get("direction", 1))

    score = {s: 0.5 for s in UNIVERSE}
    for f in factors:
        ranked = rank_values(raw[str(f["factor_id"])])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * (ranked[s] - 0.5)
    avg_iv = np.mean(list(inverse_vol.values()))
    scaling = 0.30 if vix_ratio > 1.05 else 0.20
    for s in UNIVERSE:
