ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def factors():
    try:
        x = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])
        return x if 0 < len(x) <= 10 else []
    except Exception:
        return []


def ranks(x):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / n
    return out


def bounded_weights(score):
    # Iterative projection to a diversified 15-asset, full-investment portfolio.
    w = np.array([max(score.get(s, 0.5), 1e-8) for s in UNIVERSE], dtype=float)
    w /= w.sum()
    fixed = np.zeros(15, dtype=bool)
    for _ in range(30):
        free = ~fixed
        changed = False
        for i in np.where(free)[0]:
            if w[i] < .03:
                w[i] = .03; fixed[i] = True; changed = True
            elif w[i] > .14:
                w[i] = .14; fixed[i] = True; changed = True
        if not changed:
            break
        rem = 1.0 - w[fixed].sum()
        if free.any() and w[free].sum() > 0:
            w[free] *= rem / w[free].sum()
    w = np.clip(w, .03, .14)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    fs = factors()
