        vp = np.asarray(vd.sort_values("date")["close"], dtype=float)
        vr = float(np.clip(vp[-1] / max(np.median(vp[-120:]), 1e-8), .5, 2.0))
    except Exception:
        vr = 1.0
    raw = {str(f["factor_id"]): {} for f in fs}
    iv = {}
    for s, r in ret.items():
        cum = lambda n: float(np.prod(1.0 + r[-n:]) - 1.0)
        r10, r20, r30, r40, r60 = [cum(n) for n in (10, 20, 30, 40, 60)]
        v20, v40 = max(np.std(r[-20:]), .008), max(np.std(r[-40:]), .008)
