        vals = {
            "downside_adjusted_momentum": r30 / down,
            "relative_momentum": r40 / v40,
            "range_momentum_blend": .5 * r10 / v20 + .5 * r20 / v40,
            "risk_scaled_relative_deceleration": (r60 / 3.0 - r20) / v40,
            "vix_regime_reversal": -r20 * vr / v40,
            "vol_compression_reversal": -cum(15) / max(np.std(r[-60:]), .008),
            "residual_trend": (r20 - beta * m20) / v40,
        }
        for f in fs:
