from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (register_hook, get_stock_daily_data,
    get_index_daily_data, rebalance_to_weights)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factor_ensemble.json"
LAST_BLOCK = None


def load_factors():
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []


def rank(values):
    good = [(s, v) for s, v in values.items() if np.isfinite(v)]
    out = {s: .5 for s in UNIVERSE}
    if not good:
        return out
    good.sort(key=lambda z: z[1])
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out


def capped_weights(score):
    # Full investment, 3%-14% bounds: defensive tilt is expressed within the
    # tradable universe and never as a cash sleeve.
    w = np.array([max(score.get(s, .5), 1e-8) for s in UNIVERSE], float)
    w /= w.sum()
    for _ in range(50):
        low, high = w < .03, w > .14
        if not (low.any() or high.any()):
            break
        fixed = low | high
        w[low], w[high] = .03, .14
        rest = ~fixed
        if rest.any():
            rem = 1.0 - w[fixed].sum()
            w[rest] *= rem / max(w[rest].sum(), 1e-12)
    w = np.clip(w, .03, .14)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    fs = load_factors()
    if not fs:
        return
    prices = {}
    for s in UNIVERSE:
        try:
            d = get_stock_daily_data(symbol=s, days=240)
            if d is not None and len(d) >= 80:
                p = np.asarray(d.sort_values("date")["close"], float)
                if np.all(np.isfinite(p)) and np.all(p > 0):
                    prices[s] = p
        except Exception:
            continue
    if len(prices) < 12:
        return
    try:
        d = get_stock_daily_data(symbol=next(iter(prices)), days=2)
        date = str(d.sort_values("date").iloc[-1]["date"])[:10]
        block = int(np.busday_count("2020-01-01", date) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    rets = {s: p[1:] / p[:-1] - 1 for s, p in prices.items()}
    n = min(len(x) for x in rets.values())
    market = np.mean([x[-min(60, n):] for x in rets.values()], axis=0)
    try:
        vd = get_index_daily_data(symbol="VIX", days=160)
        vp = np.asarray(vd.sort_values("date")["close"], float)
        vix_ratio = float(np.clip(vp[-1] / max(np.median(vp[-120:]), 1e-8), .5, 2.0))
    except Exception:
        vix_ratio = 1.0

    def comp(r, k):
        return float(np.prod(1 + r[-k:]) - 1)
    raw = {str(f["factor_id"]): {} for f in fs}
    invvol = {}
    for s, r in rets.items():
        r10, r20, r30, r40, r60 = [comp(r, k) for k in (10, 20, 30, 40, 60)]
        v20, v40 = max(np.std(r[-20:]), .008), max(np.std(r[-40:]), .008)
        neg = r[-40:][r[-40:] < 0]
        down = max(np.std(neg) if len(neg) >= 5 else v40, .008)
        invvol[s] = 1.0 / v20
        beta = float(np.cov(r[-60:], market[-60:])[0, 1] / max(np.var(market[-60:]), 1e-8))
        m20, m60 = comp(market, 20), comp(market, 60)
        vals = {
          "risk_scaled_relative_deceleration": (r60 / 3 - r20) / v40,
          "downside_adjusted_momentum": r30 / down,
          "downside_risk_reversal": -r20 / (v40 + down),
          "vix_regime_reversal": -r20 * vix_ratio / v40,
          "vol_adjusted_acceleration": (comp(r, 5) / v20) - (r20 / v40),
          "risk_scaled_trend_contrarian": -r20 / v40,
          "risk_adjusted_multihorizon_reversal": -(r10 + .5*r20 + .25*r40) / v40,
        }
        for f in fs:
            fid = str(f["factor_id"])
            key = next((k for k in vals if k in fid), None)
            raw[fid][s] = vals.get(key, 0.0) * int(f.get("direction", 1))

    score = {s: .5 for s in UNIVERSE}
    for f in fs:
        rr = rank(raw[str(f["factor_id"])])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * (rr[s] - .5)
    avg_iv = np.mean(list(invvol.values()))
    risk_scale = .40 if vix_ratio > 1.05 else .20
    for s in UNIVERSE:
        score[s] *= (1-risk_scale) + risk_scale * invvol[s] / avg_iv
    market20, market60 = comp(market, 20), comp(market, 60)
    if vix_ratio > 1.05 and market20 < 0 and market60 < .04:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] *= 1.12
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"):
            score[s] *= .88
    target = capped_weights(score)
    mu, sig = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01 * (score[s] - mu) / sig) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in fs],
                         horizon_days=10)

