ENSEMBLE = Path(__file__).parent / "factor_ensemble.json"
LAST_BLOCK = None


def load_factors():
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []


def rank(values):
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if good:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def capped_weights(score):
    w = np.array([max(float(score.get(s, .5)), 1e-8) for s in UNIVERSE])
    w /= w.sum()
    # High-risk bear regime: diversified full investment, with defensive assets
    # favored by score rather than a cash sleeve.
    for _ in range(100):
        lo, hi = w < .03, w > .14
        if not (lo.any() or hi.any()):
            break
        fixed = lo | hi
        w[lo], w[hi] = .03, .14
        rest = ~fixed
        if rest.any():
            w[rest] *= (1.0 - w[fixed].sum()) / max(w[rest].sum(), 1e-12)
    w = np.clip(w, .03, .14)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


