            if "risk_scaled_relative_deceleration" in fid:
                key = "deceleration"
            elif "vol_contraction_reversal" in fid:
                key = "vol_contraction"
            elif "vix_regime_reversal" in fid:
                key = "vix_reversal"
            elif "downside_adjusted_momentum" in fid:
                key = "downside_adjusted_momentum"
            elif "breadth_conditioned_reversal" in fid:
                key = "breadth_reversal"
            elif "vol_adjusted_acceleration" in fid:
                key = "vol_adjusted_acceleration"
            elif "relative_momentum" in fid:
                key = "relative_momentum"
            else:
                key = "relative_momentum"
            raw[fid][s] = vals[key] * int(f.get("direction", 1))

