import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factor_ensemble.json"
LAST_BLOCK = None


def factors():
    try:
        x = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])
        return x if 0 < len(x) <= 10 else []
    except Exception:
        return []


def pct(r, n):
    return float(np.prod(1.0 + r[-n:]) - 1.0)


def ranks(x):
    out = {s: .5 for s in UNIVERSE}
    a = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    for i, (s, _) in enumerate(a):
        out[s] = (i + 1.0) / len(a)
    return out


def weights(score):
    # Full investment, long-only, diversified. Bounds are feasible for 15 assets.
    w = np.array([max(float(score.get(s, .5)), 1e-8) for s in UNIVERSE])
    w /= w.sum()
    for _ in range(30):
        over = w > .14
        under = w < .03
        if not (over.any() or under.any()):
            break
        fixed = over.copy()
        excess = float(np.maximum(w - .14, 0).sum())
        w[over] = .14
        # Raise the lowest names first, then renormalize the free sleeve.
        free = ~fixed
        if free.any():
            w[free] = np.maximum(w[free], .03)
            w[free] *= (1.0 - w[fixed].sum()) / w[free].sum()
    w = np.maximum(w, .03)
    w /= w.sum()
    # Numerical cleanup while retaining the concentration ceiling.
    for _ in range(20):
        hi = int(np.argmax(w))
        if w[hi] <= .14 + 1e-10:
            break
        excess = w[hi] - .14
        w[hi] = .14
        lo = int(np.argmin(w))
        w[lo] += excess
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    fs = factors()
    if not fs:
        return
    prices = {}
    for s in UNIVERSE:
        try:
            d = get_stock_daily_data(symbol=s, days=240)
            if d is None:
                continue
            p = np.asarray(d.sort_values("date")["close"], dtype=float)
            if len(p) >= 80 and np.all(np.isfinite(p)) and np.all(p > 0):
                prices[s] = p
        except Exception:
            pass
    if len(prices) < 12:
        return
    try:
        d = get_stock_daily_data(symbol=next(iter(prices)), days=3)
        date = str(d.sort_values("date").iloc[-1]["date"])[:10]
        block = int(np.busday_count("2020-01-01", date) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    raw = {str(f["factor_id"]): {} for f in fs}
    inv = {}
    for s, p in prices.items():
        r = p[1:] / p[:-1] - 1.0
        v10 = max(np.std(r[-10:]), .008)
        v20 = max(np.std(r[-20:]), .008)
        v40 = max(np.std(r[-40:]), .008)
        neg = r[-40:][r[-40:] < 0]
        down = max(np.std(neg) if len(neg) >= 5 else v40, .008)
        r5, r10, r20, r30, r40, r60 = [pct(r, n) for n in (5, 10, 20, 30, 40, 60)]
        inv[s] = 1.0 / v20
        vals = {
            "deceleration": (r60 / 3.0 - r20) / v40,
            "downside_adjusted_momentum": r30 / down,
            # Prefer assets that recently mean-revert after a quiet volatility spell.
            "vol_contraction_reversal": (-r10 / v10) * min(v40 / v10, 2.0),
            "vix_regime_reversal": -r20 / v40,
            "vol_adjusted_acceleration": r5 / v10 - r20 / v40,
            "downside_risk_reversal": -r20 / down,
            "range_momentum_blend": .5 * r20 / v40 - .5 * r10 / v10,
        }
        for f in fs:
            fid = str(f["factor_id"])
