ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_factors():
    try:
        x = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])
        return x if 0 < len(x) <= 10 else []
    except Exception:
        return []


def compound(r, n):
    return float(np.prod(1.0 + r[-n:]) - 1.0)


def rank_map(x):
    out = {s: .5 for s in UNIVERSE}
    a = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    if not a:
        return out
    for i, (s, _) in enumerate(a):
        out[s] = (i + 1.) / len(a)
    return out


def bounded_weights(score):
    w = np.array([max(float(score.get(s, .5)), 1e-8) for s in UNIVERSE])
    w /= w.sum()
    # Full investment, diversified 15-asset portfolio; no cash sleeve.
    for _ in range(100):
        lo, hi = w < .03, w > .14
        if not (lo.any() or hi.any()):
            break
        fixed = lo | hi
        w[lo], w[hi] = .03, .14
        free = ~fixed
        if free.any():
            w[free] *= (1. - w[fixed].sum()) / w[free].sum()
    w = np.maximum(w, .03)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    factors = load_factors()
    if not factors:
        return
    prices = {}
    for s in UNIVERSE:
        try:
            d = get_stock_daily_data(symbol=s, days=240)
            if d is not None:
                p = np.asarray(d.sort_values("date")["close"], dtype=float)
                if len(p) >= 80 and np.all(np.isfinite(p)) and np.all(p > 0):
                    prices[s] = p
        except Exception:
            pass
    if len(prices) < 12:
        return
    try:
        d = get_stock_daily_data(symbol=next(iter(prices)), days=3)
        date = str(d.sort_values("date").iloc[-1]["date"])[:10]
        block = int(np.busday_count("2020-01-01", date) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    returns, invvol, raw = {}, {}, {str(f["factor_id"]): {} for f in factors}
    for s, p in prices.items():
        r = p[1:] / p[:-1] - 1.
        returns[s] = r
        v10 = max(float(np.std(r[-10:])), .008)
        v20 = max(float(np.std(r[-20:])), .008)
        v40 = max(float(np.std(r[-40:])), .008)
        neg = r[-40:][r[-40:] < 0]
        down = max(float(np.std(neg)) if len(neg) >= 5 else v40, .008)
        r20, r30, r40, r60 = [compound(r, n) for n in (20, 30, 40, 60)]
        hi, lo = np.max(p[-60:]), np.min(p[-60:])
        range_pos = (p[-1] - lo) / max(hi - lo, 1e-12)
        vals = {
            "deceleration": (r60 / 3. - r20) / v40,
            "downside_adjusted_momentum": r30 / down,
            "range_momentum_blend": .6 * r20 / v20 + .4 * (range_pos - .5),
            "defensive_breadth_reversal": -r20 / v40,
            "vix_regime_reversal": -r20 / v40,
            "vol_contraction_reversal": -r20 / v40,
            "trend_contrarian": -r20 / v40,
        }
        invvol[s] = 1. / v20
        for f in factors:
            fid = str(f["factor_id"])
            if "risk_scaled_relative_deceleration" in fid: key = "deceleration"
            elif "downside_adjusted_momentum" in fid: key = "downside_adjusted_momentum"
            elif "range_momentum_blend" in fid: key = "range_momentum_blend"
            elif "defensive_breadth_reversal" in fid: key = "defensive_breadth_reversal"
            elif "vix_regime_reversal" in fid: key = "vix_regime_reversal"
            elif "vol_contraction_reversal" in fid: key = "vol_contraction_reversal"
            elif "risk_scaled_trend_contrarian" in fid: key = "trend_contrarian"
            else: key = "downside_adjusted_momentum"
            raw[fid][s] = vals[key] * float(f.get("direction", 1))

    score = {s: .5 for s in UNIVERSE}
    for f in factors:
        rr = rank_map(raw[str(f["factor_id"])])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * (rr[s] - .5)

    market_trend = float(np.mean([compound(r, 60) for r in returns.values()]))
    stressed = False
    try:
        vd = get_index_daily_data(symbol="VIX", days=160)
        vp = np.asarray(vd.sort_values("date")["close"], dtype=float)
        stressed = len(vp) >= 120 and vp[-1] > 1.05 * np.median(vp[-120:])
    except Exception:
        pass
    if stressed or market_trend < 0:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 1.12
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"): score[s] *= .90
    avg_iv = float(np.mean(list(invvol.values())))
    for s in UNIVERSE:
        score[s] *= .8 + .2 * invvol.get(s, avg_iv) / avg_iv
    target = bounded_weights(score)
    mu, sig = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(.01 * (score[s] - mu) / sig) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in factors], horizon_days=10)

