UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_factors():
    try:
        fs = json.loads(ENSEMBLE.read_text()).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []


def compound(r, n):
    return float(np.prod(1.0 + r[-n:]) - 1.0)


def percentile(values):
    finite = sorted((v, s) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if finite:
        for i, (_, s) in enumerate(finite):
            out[s] = (i + 1.0) / len(finite)
    return out


def bounded(scores):
    # High-risk, 15-asset, fully invested portfolio; caps avoid crypto/high-beta concentration.
    w = np.array([max(float(scores.get(s, .5)), 1e-8) for s in UNIVERSE])
    w /= w.sum()
    for _ in range(30):
        low, high = w < .03, w > .14
        if not (low.any() or high.any()):
            break
        fixed = low | high
        w[low], w[high] = .03, .14
        free = ~fixed
        if free.any():
            w[free] *= (1.0 - w[fixed].sum()) / w[free].sum()
    w = np.maximum(w, .03)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    factors = load_factors()
    if not factors:
        return
    prices = {}
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=240)
            if df is not None:
                p = np.asarray(df.sort_values("date")["close"], dtype=float)
                if len(p) >= 80 and np.all(np.isfinite(p)) and np.all(p > 0):
                    prices[symbol] = p
        except Exception:
            pass
    if len(prices) < 12:
        return
    try:
        probe = get_stock_daily_data(symbol="SPX", days=3)
        date = str(probe.sort_values("date").iloc[-1]["date"])[:10]
        block = int(np.busday_count("2020-01-01", date) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    raw = {str(f["factor_id"]): {} for f in factors}
    invvol, trailing = {}, {}
    for symbol, p in prices.items():
        r = p[1:] / p[:-1] - 1.0
        v10 = max(float(np.std(r[-10:])), .008)
        v20 = max(float(np.std(r[-20:])), .008)
        v40 = max(float(np.std(r[-40:])), .008)
        neg = r[-40:][r[-40:] < 0]
        downside = max(float(np.std(neg)) if len(neg) >= 5 else v40, .008)
        r10, r20, r30, r40, r60 = (compound(r, n) for n in (10, 20, 30, 40, 60))
        trailing[symbol] = r60
        invvol[symbol] = 1.0 / v20
        hi, lo = np.max(p[-60:]), np.min(p[-60:])
        location = (p[-1] - lo) / max(hi - lo, 1e-12)
        # Proxies are deliberately simple and use only completed history.
        vals = {
            "decel": (r60 / 3.0 - r20) / v40,
            "contrarian": -r20 / v40,
            "contraction": -v10 / v40 + 0.5 * (-r10 / v20),
            "vix": -r20 / v40,
            "downmom": r30 / downside,
            "range": .6 * r20 / v20 + .4 * (location - .5),
            "downrev": -r20 / downside + 0.35 * (-r10 / v20),
        }
        for factor in factors:
            fid = str(factor["factor_id"])
            if "relative_deceleration" in fid:
                key = "decel"
            elif "vol_contraction" in fid:
                key = "contraction"
            elif "trend_contrarian" in fid:
                key = "contrarian"
            elif "vix_regime" in fid:
                key = "vix"
            elif "downside_adjusted_momentum" in fid:
                key = "downmom"
            elif "range_momentum_blend" in fid:
                key = "range"
            elif "downside_risk_reversal" in fid:
                key = "downrev"
            else:
                key = "contrarian"
            raw[fid][symbol] = vals[key] * float(factor.get("direction", 1))

    score = {s: .5 for s in UNIVERSE}
    for factor in factors:
        fid = str(factor["factor_id"])
        ranks = percentile(raw[fid])
        for s in UNIVERSE:
            score[s] += float(factor["weight"]) * (ranks[s] - .5)

    # High-volatility rebound: retain momentum but tilt to defensive tradable instruments.
    risk_high = False
    try:
        vdf = get_index_daily_data(symbol="VIX", days=160)
        vp = np.asarray(vdf.sort_values("date")["close"], dtype=float)
        risk_high = len(vp) >= 120 and vp[-1] > 1.05 * np.median(vp[-120:])
    except Exception:
        pass
    if risk_high or np.mean(list(trailing.values())) < 0:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] *= 1.12
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"):
            score[s] *= .90
    mean_inv = np.mean(list(invvol.values()))
    for s in UNIVERSE:
        score[s] *= .8 + .2 * invvol.get(s, mean_inv) / mean_inv
    target = bounded(score)
    center, scale = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-9)
    forecast = {s: float(.01 * (score[s] - center) / scale) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in factors], horizon_days=10)
