def rank(values):
    good = sorted((v, s) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    for i, (_, s) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out


def bounded_weights(scores):
    # Full investment, with sensible diversification for a 15-asset universe.
    w = np.array([max(float(scores.get(s, .5)), 1e-6) for s in UNIVERSE])
    w /= w.sum()
    for _ in range(30):
