            "vixrev": -r20 / v40,
            "downrev": -r20 / downside - 0.35 * r10 / v20,
        }
        for f in factors:
            fid = str(f["factor_id"])
            raw[fid][symbol] = values[kind(fid)] * float(f.get("direction", 1))

    score = {s: 0.5 for s in UNIVERSE}
