        bearish = bearish or (len(vix) >= 120 and vix[-1] > 1.05 * np.median(vix[-120:]))
    except Exception:
        pass
    if bearish:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] *= 1.25
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"):
            score[s] *= 0.80

    avg_invvol = float(np.mean(list(invvol.values())))
    for s in UNIVERSE:
        score[s] *= 0.8 + 0.2 * invvol.get(s, avg_invvol) / max(avg_invvol, 1e-12)

    target = bounded_weights(score)
    center = float(np.mean(list(score.values())))
    spread = max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(0.01 * (score[s] - center) / spread) for s in UNIVERSE}
    rebalance_to_weights(
        target,
        forecast_returns=forecast,
        factor_ids=[str(f["factor_id"]) for f in factors],
        horizon_days=10,
    )

