import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        x = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])
        return x if 0 < len(x) <= 10 else []
    except Exception:
        return []


def ranks(values):
    out = {s: .5 for s in UNIVERSE}
    good = sorted((v, s) for s, v in values.items() if np.isfinite(v))
    for i, (_, s) in enumerate(good):
        out[s] = (i + 1.) / len(good)
    return out


def bounded(score):
    w = np.array([max(float(score.get(s, .5)), 1e-8) for s in UNIVERSE])
    w /= w.sum()
    # 3% floor and 14% cap, followed by exact normalization.
    for _ in range(20):
        lo, hi = w < .03, w > .14
        if not (lo.any() or hi.any()):
            break
        fixed = lo | hi
        w[lo], w[hi] = .03, .14
        free = ~fixed
        if free.any():
            w[free] *= (1. - w[fixed].sum()) / max(w[free].sum(), 1e-12)
    w = np.maximum(w, .03)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


def kind(fid):
    if "risk_scaled_relative_deceleration" in fid: return "decel"
    if "vix_regime_reversal" in fid: return "vix"
    if "vol_contraction_reversal" in fid: return "volcontract"
    if "range_momentum_blend" in fid: return "range20"
    if "vol_adjusted_acceleration" in fid: return "accel"
    if "downside_adjusted_momentum" in fid: return "down30"
    if "relative_momentum_40d" in fid: return "mom40"
    return "range20"


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    factors = load_ensemble()
    if not factors:
        return
    prices = {}
    for s in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=s, days=240)
            if df is not None:
                p = np.asarray(df.sort_values("date")["close"], dtype=float)
                if len(p) >= 80 and np.all(np.isfinite(p)) and np.all(p > 0): prices[s] = p
        except Exception:
            pass
    if len(prices) < 12: return
    try:
        dt = get_stock_daily_data(symbol="SPX", days=3).sort_values("date").iloc[-1]["date"]
        block = int(np.busday_count("2020-01-01", str(dt)[:10]) // 10)
    except Exception:
        return
    if block == LAST_BLOCK: return
    LAST_BLOCK = block

    raw = {str(f["factor_id"]): {} for f in factors}
    invvol, trend = {}, {}
    for s, p in prices.items():
        r = p[1:] / p[:-1] - 1.
        v10, v20, v30, v40 = [max(float(np.std(r[-n:])), .008) for n in (10,20,30,40)]
        neg = r[-40:][r[-40:] < 0]
        downside = max(float(np.std(neg)) if len(neg) >= 5 else v40, .008)
        r10, r20, r30, r40 = p[-1]/p[-11]-1, p[-1]/p[-21]-1, p[-1]/p[-31]-1, p[-1]/p[-41]-1
        invvol[s], trend[s] = 1./v20, r40
        vals = {
            "mom40": r40/v40,
            "range20": (.6*r20 + .4*r10)/v20,
            "accel": r10/v10 - r20/v20,
            "down30": r30/downside,
            "decel": -(r20/v20 - r10/v10)/v20,
            "vix": -r20/v40,
            "volcontract": -v20/max(v40, .008),
        }
        for f in factors:
            fid = str(f["factor_id"])
            raw[fid][s] = vals[kind(fid)] * float(f.get("direction", 1))

    score = {s: .5 for s in UNIVERSE}
    for f in factors:
        rr = ranks(raw[str(f["factor_id"])])
        for s in UNIVERSE: score[s] += float(f["weight"]) * (rr[s] - .5)
    bearish = np.mean(list(trend.values())) < 0.
    try:
        v = np.asarray(get_index_daily_data(symbol="VIX", days=160).sort_values("date")["close"], dtype=float)
        bearish = bearish or (len(v) >= 120 and v[-1] > 1.05*np.median(v[-120:]))
    except Exception: pass
    if bearish:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 1.25
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"): score[s] *= .80
    avg = np.mean(list(invvol.values()))
    for s in UNIVERSE: score[s] *= .85 + .15*invvol.get(s, avg)/max(avg, 1e-12)
    target = bounded(score)
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-9)
    forecast = {s: float(.01*(score[s]-mean)/sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in factors], horizon_days=10)

