from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        fs = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []


def cross_rank(vals):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((float(v), s) for s, v in vals.items() if np.isfinite(v))
    if good:
        for i, (_, s) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def bounded(score):
    w = np.array([max(float(score.get(s, 0.5)), 1e-8) for s in UNIVERSE])
    w /= w.sum()
    # Diversified full-investment portfolio; fractional quantities are handled by helper.
    for _ in range(30):
        low, high = w < 0.03, w > 0.14
        if not (low.any() or high.any()):
            break
        fixed = low | high
        w[low], w[high] = 0.03, 0.14
        free = ~fixed
        if free.any():
            w[free] *= (1.0 - w[fixed].sum()) / max(w[free].sum(), 1e-12)
    w = np.maximum(w, 0.03)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


def factor_kind(fid):
    if "risk_scaled_relative_deceleration" in fid: return "decel"
    if "vix_regime_reversal" in fid: return "vix"
    if "vol_contraction_reversal" in fid: return "volcontract"
    if "downside_risk_reversal" in fid: return "downrisk"
    if "range_momentum_blend" in fid: return "range20"
    if "downside_adjusted_momentum" in fid: return "down30"
    if "relative_momentum_40d" in fid: return "mom40"
    return "range20"


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    factors = load_ensemble()
    if not factors:
        return
    prices = {}
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=240)
            if df is None:
                continue
            p = np.asarray(df.sort_values("date")["close"], dtype=float)
            if len(p) >= 80 and np.all(np.isfinite(p)) and np.all(p > 0):
                prices[symbol] = p
        except Exception:
            continue
    if len(prices) < 12:
        return
    try:
        d = get_stock_daily_data(symbol="SPX", days=3).sort_values("date").iloc[-1]["date"]
        block = int(np.busday_count("2020-01-01", str(d)[:10]) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    raw = {str(f["factor_id"]): {} for f in factors}
    invvol, trend = {}, {}
    for symbol, p in prices.items():
        ret = p[1:] / p[:-1] - 1.0
        v10, v20, v30, v40 = [max(float(np.std(ret[-n:])), 0.008) for n in (10, 20, 30, 40)]
        neg = ret[-40:][ret[-40:] < 0]
        downside = max(float(np.std(neg)) if len(neg) >= 5 else v40, 0.008)
        r10 = p[-1] / p[-11] - 1.0
        r20 = p[-1] / p[-21] - 1.0
        r30 = p[-1] / p[-31] - 1.0
        r40 = p[-1] / p[-41] - 1.0
        invvol[symbol], trend[symbol] = 1.0 / v20, r40
        vals = {
            "decel": -(r20 / v20 - r10 / v10) / v20,
            "vix": -r20 / v40,
            "volcontract": -v20 / max(v40, 0.008),
            "downrisk": -r20 / downside,
            "range20": (0.6 * r20 + 0.4 * r10) / v20,
            "down30": r30 / downside,
            "mom40": r40 / v40,
        }
        for f in factors:
            fid = str(f["factor_id"])
            raw[fid][symbol] = vals[factor_kind(fid)] * float(f.get("direction", 1))

    score = {s: 0.5 for s in UNIVERSE}
    for f in factors:
        rr = cross_rank(raw[str(f["factor_id"])])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * (rr[s] - 0.5)

    # Medium-high, choppy regime: use defensive tradables, never cash.
    bearish = np.mean(list(trend.values())) < 0.0
    try:
        vix = np.asarray(get_index_daily_data(symbol="VIX", days=160).sort_values("date")["close"], dtype=float)
        bearish = bearish or (len(vix) >= 120 and vix[-1] > 1.05 * np.median(vix[-120:]))
    except Exception:
        pass
    if bearish:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 1.25
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"): score[s] *= 0.80

    avg_invvol = np.mean(list(invvol.values()))
    for s in UNIVERSE:
        score[s] *= 0.85 + 0.15 * invvol.get(s, avg_invvol) / max(avg_invvol, 1e-12)
    target = bounded(score)
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-9)
    forecast = {s: float(0.01 * (score[s] - mean) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in factors], horizon_days=10)

