import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ROOT = Path(__file__).parent
ENSEMBLE_PATHS = [ROOT / "factor_ensemble.json", ROOT / "factors" / "factor_ensemble.json"]
LAST_BLOCK = None


def load_ensemble():
    for path in ENSEMBLE_PATHS:
        try:
            factors = json.loads(path.read_text(encoding="utf-8")).get("selected_factors", [])
            if 0 < len(factors) <= 10:
                return factors
        except Exception:
            pass
    return []


def rank_map(values):
    result = {s: 0.5 for s in UNIVERSE}
    valid = sorted((float(v), s) for s, v in values.items() if np.isfinite(v))
    for i, (_, symbol) in enumerate(valid):
