import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX",
            "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        x = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])
        return x if 0 < len(x) <= 10 else []
    except Exception:
        return []


def percentile_rank(values):
    good = [(float(v), s) for s, v in values.items() if np.isfinite(v)]
    out = {s: .5 for s in UNIVERSE}
    if not good:
        return out
    good.sort()
    for i, (_, s) in enumerate(good):
        out[s] = (i + 1) / len(good)
    return out


def kind(fid):
    for k in ("risk_scaled_relative_deceleration", "vol_contraction_reversal",
              "vix_regime_reversal", "downside_risk_reversal",
              "downside_adjusted_momentum", "range_momentum_blend"):
        if k in fid:
            return k
    return "range_momentum_blend"


def bounded_weights(score):
    # Iterative water-filling keeps every tradable asset invested, with 3%-14% bounds.
    w = np.array([max(float(score.get(s, .5)), 1e-8) for s in UNIVERSE])
    w /= w.sum()
    for _ in range(50):
        low, high = w < .03, w > .14
        if not (low.any() or high.any()):
            break
        fixed = low | high
        w[low], w[high] = .03, .14
        free = ~fixed
        if free.any():
            remainder = 1.0 - w[fixed].sum()
            w[free] *= max(remainder, 0.0) / w[free].sum()
    w = np.clip(w, .03, .14)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    ensemble = load_ensemble()
    if not ensemble:
        return

    prices = {}
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=240)
            if df is None:
                continue
            p = np.asarray(df.sort_values("date")["close"], dtype=float)
            if len(p) >= 80 and np.all(np.isfinite(p)) and np.all(p > 0):
                prices[symbol] = p
        except Exception:
            continue
    if len(prices) < 12:
        return

    # Deterministic ten-trading-day gate, using only the last completed bar.
    try:
        d = get_stock_daily_data(symbol="SPX", days=3).sort_values("date")
        block = int(np.busday_count("2020-01-01", str(d.iloc[-1]["date"])[:10]) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    raw = {str(f["factor_id"]): {} for f in ensemble}
    invvol, breadth_returns = {}, []
    for symbol, p in prices.items():
        ret = p[1:] / p[:-1] - 1.0
        vol10 = max(float(np.std(ret[-10:])), .008)
        vol20 = max(float(np.std(ret[-20:])), .008)
        vol40 = max(float(np.std(ret[-40:])), .008)
        neg = ret[-40:][ret[-40:] < 0]
        downside = max(float(np.std(neg)) if len(neg) >= 5 else vol40, .008)
        r10, r20, r30, r40 = (p[-1] / p[-n-1] - 1.0 for n in (10, 20, 30, 40))
        invvol[symbol] = 1.0 / vol20
        breadth_returns.append(r40)
        # Positive values are deliberately aligned with the persisted +1 directions.
        vals = {
            "risk_scaled_relative_deceleration": ((r40 / 3.0) - r20) / vol40,
            "vol_contraction_reversal": -r20 * vol40 / vol10,
            "vix_regime_reversal": -r20 / vol40,
            "downside_risk_reversal": -r20 / downside,
            "downside_adjusted_momentum": r30 / downside,
            "range_momentum_blend": (.6 * r20 + .4 * r10) / vol20,
        }
        for f in ensemble:
            fid = str(f["factor_id"])
            raw[fid][symbol] = vals[kind(fid)] * float(f.get("direction", 1))

    score = {s: .5 for s in UNIVERSE}
    for f in ensemble:
        fid = str(f["factor_id"])
        ranks = percentile_rank(raw[fid])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * (ranks[s] - .5)

    defensive = float(np.mean(breadth_returns)) < 0.0
    try:
        vix = get_index_daily_data(symbol="VIX", days=160)
        vp = np.asarray(vix.sort_values("date")["close"], dtype=float)
        defensive |= len(vp) >= 120 and vp[-1] > 1.05 * np.median(vp[-120:])
    except Exception:
        pass
    if defensive:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] *= 1.25
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"):
            score[s] *= .80

    avg_iv = float(np.mean(list(invvol.values())))
    for s in UNIVERSE:
        score[s] *= .85 + .15 * invvol.get(s, avg_iv) / avg_iv
    target = bounded_weights(score)
    mean_score = float(np.mean(list(score.values())))
    std_score = max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(.01 * (score[s] - mean_score) / std_score) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in ensemble], horizon_days=10)

