from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def factors():
    try:
        fs = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []


def rank(vals):
    out = {s: 0.5 for s in UNIVERSE}
    a = sorted((v, s) for s, v in vals.items() if np.isfinite(v))
    for i, (_, s) in enumerate(a):
        out[s] = (i + 1) / len(a)
    return out


def factor_kind(fid):
    for key, name in (("risk_scaled_relative_deceleration", "decel"),
                      ("vol_contraction_reversal", "contract"),
                      ("vix_regime_reversal", "vix"),
                      ("downside_risk_reversal", "downrisk"),
                      ("downside_adjusted_momentum", "momentum"),
                      ("range_momentum_blend", "range")):
        if key in fid:
            return name
    return "range"


def weights(scores):
    # Full investment, diversified across the intentionally small universe.
    w = np.array([max(scores.get(s, 0.5), 1e-8) for s in UNIVERSE], dtype=float)
    w /= w.sum()
    for _ in range(20):
        lo, hi = w < .03, w > .14
        if not (lo.any() or hi.any()):
            break
        fixed = lo | hi
        w[lo], w[hi] = .03, .14
        free = ~fixed
        if free.any():
            w[free] *= (1 - w[fixed].sum()) / w[free].sum()
    w = np.maximum(w, .03)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    fs = factors()
    if not fs:
        return
    px = {}
    for s in UNIVERSE:
        try:
            d = get_stock_daily_data(symbol=s, days=240)
            if d is not None:
                p = np.asarray(d.sort_values("date")["close"], dtype=float)
                if len(p) >= 80 and np.all(np.isfinite(p)) and np.all(p > 0):
                    px[s] = p
        except Exception:
            pass
    if len(px) < 12:
        return
    try:
        d = get_stock_daily_data(symbol="SPX", days=3).sort_values("date")
        block = int(np.busday_count("2020-01-01", str(d.iloc[-1]["date"])[:10]) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    raw = {str(f["factor_id"]): {} for f in fs}
    invvol, trends = {}, []
    for s, p in px.items():
        r = p[1:] / p[:-1] - 1
        v = {n: max(float(np.std(r[-n:])), .008) for n in (10, 20, 30, 40)}
        neg = r[-40:][r[-40:] < 0]
        dv = max(float(np.std(neg)) if len(neg) >= 5 else v[40], .008)
        rr = {n: p[-1] / p[-n-1] - 1 for n in (10, 20, 30, 40)}
        invvol[s] = 1 / v[20]
        trends.append(rr[40])
        val = {"decel": -(rr[20]/v[20] - rr[10]/v[10])/v[20],
               "contract": -v[20]/v[40], "vix": -rr[20]/v[40],
               "downrisk": -rr[20]/dv, "momentum": rr[30]/dv,
               "range": (.6*rr[20] + .4*rr[10])/v[20]}
        for f in fs:
            fid = str(f["factor_id"])
            raw[fid][s] = val[factor_kind(fid)] * float(f.get("direction", 1))

    score = {s: .5 for s in UNIVERSE}
    for f in fs:
        fid = str(f["factor_id"])
        rk = rank(raw[fid])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * (rk[s] - .5)

    defensive = np.mean(trends) < 0
    try:
        vd = get_index_daily_data(symbol="VIX", days=160)
        vv = np.asarray(vd.sort_values("date")["close"], dtype=float)
        defensive |= len(vv) >= 120 and vv[-1] > 1.05 * np.median(vv[-120:])
    except Exception:
        pass
    if defensive:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 1.25
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"): score[s] *= .80
    av = np.mean(list(invvol.values()))
    for s in UNIVERSE:
        score[s] *= .85 + .15 * invvol.get(s, av) / av
    target = weights(score)
    mu, sig = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-9)
    forecast = {s: float(.01 * (score[s] - mu) / sig) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in fs], horizon_days=10)
"}

