        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []

def rank(vals):
    good = sorted((float(v), s) for s, v in vals.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    if good:
        for i, (_, s) in enumerate(good): out[s] = (i + 1) / len(good)
    return out

def signal(fid, r, p, common):
    v10 = max(np.std(r[-10:]), .008); v20 = max(np.std(r[-20:]), .008); v40 = max(np.std(r[-40:]), .008)
    neg = r[-40:][r[-40:] < 0]
    down = max(np.std(neg) if len(neg) >= 5 else v40, .008)
    r10, r20, r30, r40 = (p[-1] / p[-n-1] - 1 for n in (10, 20, 30, 40))
