import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        fs = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []


def percentile_rank(values):
    valid = sorted((float(v), s) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if not valid:
        return out
    for i, (_, s) in enumerate(valid):
        out[s] = (i + 1.0) / len(valid)
    return out


def factor_signal(fid, r, p):
    v10 = max(float(np.std(r[-10:])), 0.008)
    v20 = max(float(np.std(r[-20:])), 0.008)
    v40 = max(float(np.std(r[-40:])), 0.008)
    neg = r[-40:][r[-40:] < 0]
    down = max(float(np.std(neg)) if len(neg) >= 5 else v40, 0.008)
    r10 = p[-1] / p[-11] - 1.0
    r20 = p[-1] / p[-21] - 1.0
    r30 = p[-1] / p[-31] - 1.0
    r40 = p[-1] / p[-41] - 1.0
    if "breadth_persistence_quality" in fid:
        return r40 / v40
    if "downside_adjusted_momentum" in fid:
        return r30 / down
    if "downside_asymmetry" in fid:
        return (r10 / v10) - (r20 / down)
    if "volscaled_reversal" in fid:
        return -r30 / v30 if (v30 := max(float(np.std(r[-30:])), 0.008)) else 0.0
    if "vol_contraction_reversal" in fid:
        return -r20 * v40 / v10
    if "vix_regime_reversal" in fid:
        return -r20 / v40
    if "risk_scaled_relative_deceleration" in fid:
        return r40 / (3.0 * v40) - r20 / v20
    if "volatility_premium" in fid:
        return v20
    if "range_momentum_blend" in fid:
        return 0.6 * r20 / v20 + 0.4 * r10 / v10
    return r20 / v20


def bounded_weights(score):
    w = np.array([max(float(score.get(s, 0.0)), 1e-12) for s in UNIVERSE])
    w /= w.sum()
    for _ in range(40):
        low, high = w < 0.03, w > 0.14
        if not (low.any() or high.any()):
            break
        fixed = low | high
        w[low], w[high] = 0.03, 0.14
        free = ~fixed
        if free.any():
            w[free] *= (1.0 - w[fixed].sum()) / w[free].sum()
    w = np.clip(w, 0.03, 0.14)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    fs = load_ensemble()
    if not fs:
        return
    prices = {}
    for s in UNIVERSE:
        try:
            d = get_stock_daily_data(symbol=s, days=240)
            if d is not None:
                a = np.asarray(d.sort_values("date")["close"], dtype=float)
                if len(a) >= 80 and np.all(np.isfinite(a)) and np.all(a > 0):
                    prices[s] = a
        except Exception:
            continue
    if len(prices) < 12:
        return
    try:
        d = get_stock_daily_data(symbol="SPX", days=3).sort_values("date")
        block = int(np.busday_count("2020-01-01", str(d.iloc[-1]["date"])[:10]) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    raw = {str(f["factor_id"]): {} for f in fs}
    invvol = {}
    for s, p in prices.items():
        r = p[1:] / p[:-1] - 1.0
        invvol[s] = 1.0 / max(float(np.std(r[-20:])), 0.008)
        for f in fs:
            fid = str(f["factor_id"])
            raw[fid][s] = factor_signal(fid, r, p) * float(f.get("direction", 1))
    score = {s: 0.5 for s in UNIVERSE}
    for f in fs:
        fid = str(f["factor_id"])
        ranks = percentile_rank(raw[fid])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * (ranks[s] - 0.5)

    # High-risk transition overlay: remain fully invested but favor tradable defensives.
    defensive = np.mean([p[-1] / p[-41] - 1.0 for p in prices.values()]) < 0.0
    try:
        v = get_index_daily_data(symbol="VIX", days=160)
        vp = np.asarray(v.sort_values("date")["close"], dtype=float)
        defensive = defensive or (len(vp) >= 120 and vp[-1] > 1.05 * np.median(vp[-120:]))
    except Exception:
        pass
    if defensive:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] *= 1.40
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"):
            score[s] *= 0.65

    avg_iv = float(np.mean(list(invvol.values())))
    for s in UNIVERSE:
        score[s] *= 0.85 + 0.15 * invvol.get(s, avg_iv) / avg_iv
    target = bounded_weights(score)
    mean, stdev = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(0.01 * (score[s] - mean) / stdev) for s in UNIVERSE}
    rebalance_to_weights(
        target, forecast_returns=forecast,
        factor_ids=[str(f["factor_id"]) for f in fs], horizon_days=10,
    )

