        return factors if 0 < len(factors) <= 10 else []
    except Exception:
        return []


def ranks(values):
    valid = sorted((float(v), s) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    for i, (_, symbol) in enumerate(valid):
        out[symbol] = (i + 1.0) / len(valid)
    return out


def signal(fid, returns, prices):
    v10 = max(float(np.std(returns[-10:])), 0.008)
    v20 = max(float(np.std(returns[-20:])), 0.008)
    v40 = max(float(np.std(returns[-40:])), 0.008)
    downside = returns[-40:][returns[-40:] < 0]
    downvol = max(float(np.std(downside)) if len(downside) >= 5 else v40, 0.008)
    r10 = prices[-1] / prices[-11] - 1.0
    r20 = prices[-1] / prices[-21] - 1.0
    r30 = prices[-1] / prices[-31] - 1.0
    r40 = prices[-1] / prices[-41] - 1.0
    if "breadth_persistence_quality" in fid:
        return r40 / v40
    if "volatility_premium" in fid:
        return v20
    if "risk_scaled_relative_deceleration" in fid:
        return r40 / (3.0 * v40) - r20 / v20
    if "downside_adjusted_momentum" in fid:
        return r30 / downvol
    if "vix_regime_reversal" in fid:
        return -r20 / v40
    if "vol_contraction_reversal" in fid:
        return -r20 * v40 / v10
    if "range_momentum_blend" in fid:
        return 0.6 * r20 / v20 + 0.4 * r10 / v10
    return r20 / v20


def make_weights(score):
    w = np.array([max(float(score.get(s, 0.0)), 1e-12) for s in UNIVERSE])
    w /= w.sum()
    for _ in range(50):
        low, high = w < 0.03, w > 0.14
        if not (low.any() or high.any()):
            break
        fixed = low | high
        w[low], w[high] = 0.03, 0.14
        free = ~fixed
        if free.any():
            w[free] *= (1.0 - w[fixed].sum()) / w[free].sum()
    w = np.clip(w, 0.03, 0.14)
    w /= w.sum()
    return {s: float(w[i]) for i, s in enumerate(UNIVERSE)}


