            score[symbol] *= 0.65

    avg_invvol = float(np.mean(list(invvol.values())))
    for symbol in UNIVERSE:
        score[symbol] *= 0.85 + 0.15 * invvol.get(symbol, avg_invvol) / avg_invvol
    target = make_weights(score)
    mean = float(np.mean(list(score.values())))
    stdev = max(float(np.std(list(score.values()))), 1e-9)
