import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None


def load_ensemble():
    try:
        fs = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []


def cross_rank(values):
    out = {s: 0.5 for s in UNIVERSE}
    valid = sorted((float(v), s) for s, v in values.items() if np.isfinite(v))
    if valid:
        for i, (_, s) in enumerate(valid):
            out[s] = (i + 1.0) / len(valid)
    return out


def signal(fid, returns, prices):
    v10 = max(float(np.std(returns[-10:])), 0.008)
    v20 = max(float(np.std(returns[-20:])), 0.008)
    v40 = max(float(np.std(returns[-40:])), 0.008)
    losses = returns[-40:][returns[-40:] < 0]
    downside = max(float(np.std(losses)) if len(losses) >= 5 else v40, 0.008)
    r10 = prices[-1] / prices[-11] - 1.0
    r20 = prices[-1] / prices[-21] - 1.0
    r30 = prices[-1] / prices[-31] - 1.0
    r40 = prices[-1] / prices[-41] - 1.0
    if fid == "breadth_persistence_quality_40d":
        return r40 / v40
    if fid == "volatility_premium_20d":
        return v20
    if fid == "dispersion_normalized_momentum_40d":
        return r40 / v40
    if fid == "miner_2_downside_adjusted_momentum_30d":
        return r30 / downside
    if fid == "miner_1_range_momentum_blend_20d":
        return 0.6 * r20 / v20 + 0.4 * r10 / v10
    if fid == "miner_2_20341123_downside_sharpe_momentum_40d":
        return r40 / downside
    return r20 / v20


def make_weights(score):
    # Positive score transform, then inverse-volatility adjustment. Full investment.
    x = np.array([max(float(score.get(s, 0.5)), 1e-8) for s in UNIVERSE])
    x /= x.sum()
    for _ in range(25):
        low, high = x < 0.03, x > 0.14
        if not (low.any() or high.any()):
            break
        fixed = low | high
        x[low], x[high] = 0.03, 0.14
        free = ~fixed
        if free.any():
            x[free] *= (1.0 - x[fixed].sum()) / x[free].sum()
    x = np.clip(x, 0.03, 0.14)
    x /= x.sum()
    return {s: float(x[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def cross_asset_strategy():
    global LAST_BLOCK
    factors = load_ensemble()
    if not factors:
        return
    prices = {}
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=240)
            if df is None:
                continue
            p = np.asarray(df.sort_values("date")["close"], dtype=float)
            if len(p) >= 80 and np.all(np.isfinite(p)) and np.all(p > 0):
                prices[symbol] = p
        except Exception:
            continue
    if len(prices) < 12:
        return
    try:
        ref = get_stock_daily_data(symbol="SPX", days=3).sort_values("date")
        date = str(ref.iloc[-1]["date"])[:10]
        block = int(np.busday_count("2020-01-01", date) // 10)
    except Exception:
        return
    if block == LAST_BLOCK:
        return
    LAST_BLOCK = block

    raw = {str(f["factor_id"]): {} for f in factors}
    invvol = {}
    for symbol, p in prices.items():
        r = p[1:] / p[:-1] - 1.0
        invvol[symbol] = 1.0 / max(float(np.std(r[-20:])), 0.008)
        for f in factors:
            fid = str(f["factor_id"])
            raw[fid][symbol] = signal(fid, r, p) * float(f.get("direction", 1))

    score = {s: 0.5 for s in UNIVERSE}
    for f in factors:
        fid = str(f["factor_id"])
        ranks = cross_rank(raw[fid])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * (ranks[s] - 0.5)

    # High-risk sideways/bearish regime: remain fully invested but rotate defensively.
    defensive = np.mean([p[-1] / p[-41] - 1.0 for p in prices.values()]) < 0.0
    try:
        vix = get_index_daily_data(symbol="VIX", days=160)
        vp = np.asarray(vix.sort_values("date")["close"], dtype=float)
        defensive = defensive or (len(vp) >= 120 and vp[-1] > 1.05 * np.median(vp[-120:]))
    except Exception:
        pass
    if defensive:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] *= 1.40
        for s in ("BTC", "ETH", "SOX", "NDX", "WTI"):
            score[s] *= 0.65

    avg_iv = np.mean(list(invvol.values()))
    for s in UNIVERSE:
        score[s] *= 0.85 + 0.15 * invvol.get(s, avg_iv) / avg_iv
    target = make_weights(score)
    center = np.mean(list(score.values()))
    scale = max(float(np.std(list(score.values()))), 1e-9)
    forecast = {s: float(0.01 * (score[s] - center) / scale) for s in UNIVERSE}
    rebalance_to_weights(
        target, forecast_returns=forecast,
        factor_ids=[str(f["factor_id"]) for f in factors], horizon_days=10,
    )

