LAST_BLOCK = None


def factors():
    try:
        x = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])
        return x if 0 < len(x) <= 10 else []
    except Exception:
        return []


def rank(vals):
    out = {s: 0.5 for s in UNIVERSE}
    a = sorted((v, s) for s, v in vals.items() if np.isfinite(v))
    if a:
        for i, (_, s) in enumerate(a): out[s] = (i + 1.0) / len(a)
    return out


def value(fid, p):
    p = p[:-1]  # completed sessions only
    r = p[1:] / p[:-1] - 1
    v10 = max(float(np.std(r[-10:])), .008)
    v20 = max(float(np.std(r[-20:])), .008)
    v40 = max(float(np.std(r[-40:])), .008)
    v100 = max(float(np.std(r[-100:])), .008)
    neg = r[-40:][r[-40:] < 0]
    down = max(float(np.std(neg)) if len(neg) >= 5 else v40, .008)
    r10 = p[-1] / p[-11] - 1
    r20 = p[-1] / p[-21] - 1
    r30 = p[-1] / p[-31] - 1
    r40 = p[-1] / p[-41] - 1
    if fid == "volatility_premium_20d": return v20
    if fid in ("breadth_persistence_quality_40d", "dispersion_normalized_momentum_40d"): return r40 / v40
    if fid == "miner_1_20350426_volatility_shock_reversal_40d": return -np.clip(v20 / v100 - 1, -3, 3)
    if fid == "miner_2_downside_adjusted_momentum_30d": return r30 / down
    if fid == "miner_2_20341123_downside_sharpe_momentum_40d": return r40 / down
    if fid == "miner_1_range_momentum_blend_20d": return .6 * r20 / v20 + .4 * r10 / v10
    if fid == "breadth_conditioned_calm_reversal_10d":
        # Contrarian signal is active only when recent volatility is relatively calm.
        calm = np.clip(1.0 - v10 / max(v40, .008), -1.0, 1.0)
        return -r10 / v10 * max(calm, 0.0)
    return 0.0


def make_weights(score):
    x = np.array([max(score.get(s, .5), 1e-8) for s in UNIVERSE])
    x /= x.sum()
