        if free.any(): x[free] *= (1 - x[fixed].sum()) / x[free].sum()
    x = np.maximum(x, 0); x /= x.sum()
    return {s: float(x[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def strategy():
    global LAST_BLOCK
    fs = factors()
    if not fs: return
    prices = {}
    for s in UNIVERSE:
        try:
