                if len(p) >= 125 and np.all(np.isfinite(p)) and np.all(p > 0): prices[s] = p
        except Exception: pass
    if len(prices) < 12: return
    try:
        d = get_stock_daily_data(symbol="SPX", days=3).sort_values("date")
        block = int(np.busday_count("2020-01-01", str(d.iloc[-1].date)[:10]) // 10)
    except Exception: return
    if block == LAST_BLOCK: return
    LAST_BLOCK = block
    raw = {str(f["factor_id"]): {} for f in fs}
    for s, p in prices.items():
        for f in fs:
            raw[str(f["factor_id"])][s] = value(str(f["factor_id"]), p) * float(f.get("direction", 1))
    score = {s: .5 for s in UNIVERSE}
    for f in fs:
        rr = rank(raw[str(f["factor_id"])])
        for s in UNIVERSE: score[s] += float(f["weight"]) * (rr[s] - .5)
    # High-risk rebound: favor tradable defensive benchmarks, never cash.
    try:
        q = np.asarray(get_index_daily_data(symbol="VIX", days=160).sort_values("date")["close"], float)
        if len(q) >= 120 and q[-1] > 1.05 * np.median(q[-120:]):
            for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 1.30
            for s in ("BTC", "ETH", "SOX", "NDX", "WTI"): score[s] *= .75
    except Exception: pass
    target = make_weights(score)
    c, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.01 * (score[s] - c) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
