    v10 = max(float(np.std(r[-10:])), 0.008)
    v20 = max(float(np.std(r[-20:])), 0.008)
    v40 = max(float(np.std(r[-40:])), 0.008)
    v100 = max(float(np.std(r[-100:])), 0.008)
    neg = r[-40:][r[-40:] < 0]
    downside = max(float(np.std(neg)) if len(neg) >= 5 else v40, 0.008)
