    if fid == "volatility_premium_20d": return v20
    if fid in ("breadth_persistence_quality_40d", "dispersion_normalized_momentum_40d"): return r40 / v40
    if fid == "miner_1_20350426_volatility_shock_reversal_40d": return -np.clip(v20 / v100 - 1.0, -3, 3)
