import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (register_hook, get_stock_daily_data,
    get_index_daily_data, rebalance_to_weights)

UNIVERSE = ["000300.SH","SPX","HSI","N225","SX5E","000688.SH","SOX","NDX",
            "XAU","COPPER","WTI","BTC","ETH","US10Y","CN10Y"]
ENSEMBLE = Path(__file__).parent / "factors" / "factor_ensemble.json"
LAST_BLOCK = None

def load_factors():
    try:
        fs = json.loads(ENSEMBLE.read_text(encoding="utf-8")).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []

def percentile(values):
    out = {s: .5 for s in UNIVERSE}
    a = sorted((float(v), s) for s, v in values.items() if np.isfinite(v))
    for i, (_, s) in enumerate(a):
        out[s] = (i + 1) / len(a)
    return out

def factor_value(fid, p, cross=None):
    p = p[:-1]                         # only completed sessions
    r = p[1:] / p[:-1] - 1.0
    v10 = max(float(np.std(r[-10:])), .008)
    v20 = max(float(np.std(r[-20:])), .008)
    v40 = max(float(np.std(r[-40:])), .008)
    v100 = max(float(np.std(r[-100:])), .008)
    neg = r[-40:][r[-40:] < 0]
    down = max(float(np.std(neg)) if len(neg) >= 5 else v40, .008)
    r10 = p[-1] / p[-11] - 1
    r20 = p[-1] / p[-21] - 1
    r30 = p[-1] / p[-31] - 1
    r40 = p[-1] / p[-41] - 1
    if fid == "volatility_premium_20d":
        return -v20
    if fid == "breadth_persistence_quality_40d":
        return r40 / v40
    if fid == "miner_3_20310515_risk_scaled_relative_deceleration_20d":
        return (r20 - r10) / v20
    if fid == "miner_2_downside_adjusted_momentum_30d":
        return r30 / down
    if fid == "miner_3_20310501_vix_regime_reversal_20d":
        return -r20 / v20
    if fid == "miner_2_20350621_breadth_conditioned_risk_reversal_20d":
        breadth = np.mean([cross.get(s, 0) > 0 for s in cross]) if cross else .5
        return (r20 / v20) if breadth >= .5 else (-r20 / v20)
    if fid == "miner_3_20301031_vol_adjusted_acceleration_10d":
        return (r10 - (p[-1] / p[-21] - 1)) / v10
    return 0.0

def bounded_weights(score):
    # Full investment, diversified 15-asset portfolio; no cash sleeve.
    x = np.array([max(float(score.get(s, .5)), 1e-9) for s in UNIVERSE])
    x /= x.sum()
    lo, hi = .03, .14
    for _ in range(100):
        x = np.clip(x, lo, hi)
        free = (x > lo + 1e-10) & (x < hi - 1e-10)
        residual = 1.0 - x[~free].sum()
        if not free.any(): break
