        if np.all(x >= lo - 1e-9) and np.all(x <= hi + 1e-9): break
    x = np.clip(x, 0, None)
    x /= x.sum()
    return {s: float(x[i]) for i, s in enumerate(UNIVERSE)}

@register_hook
def strategy():
    global LAST_BLOCK
    fs = load_factors()
    if not fs: return
    prices = {}
    for s in UNIVERSE:
        try:
            d = get_stock_daily_data(symbol=s, days=260)
            if d is not None:
                p = np.asarray(d.sort_values("date")["close"], float)
                if len(p) >= 125 and np.all(np.isfinite(p)) and np.all(p > 0): prices[s] = p
        except Exception: pass
    if len(prices) < 12: return
    try:
        day = get_stock_daily_data(symbol="SPX", days=3).sort_values("date").iloc[-1]["date"]
        block = int(np.busday_count("2020-01-01", str(day)[:10]) // 10)
    except Exception: return
    if block == LAST_BLOCK: return
    LAST_BLOCK = block
    # Cross-sectional raw 20-day returns are used only for the breadth gate.
    cross = {s: prices[s][-1] / prices[s][-21] - 1 for s in prices}
    score = {s: .5 for s in UNIVERSE}
    for f in fs:
        raw = {s: factor_value(str(f["factor_id"]), p, cross) * float(f.get("direction", 1))
               for s, p in prices.items()}
        rr = percentile(raw)
        for s in UNIVERSE: score[s] += float(f["weight"]) * (rr[s] - .5)
    # High VIX is a risk overlay, expressed using tradable defensive assets.
    try:
        vd = get_index_daily_data(symbol="VIX", days=160)
        v = np.asarray(vd.sort_values("date")["close"], float)
        if len(v) >= 120 and v[-1] > 1.05 * np.median(v[-120:]):
            for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 1.30
            for s in ("BTC", "ETH", "SOX", "NDX", "WTI"): score[s] *= .75
    except Exception: pass
    target = bounded_weights(score)
    vals = np.array(list(score.values()), float)
    forecast = {s: float(.01 * (score[s] - vals.mean()) / max(vals.std(), 1e-8)) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in fs], horizon_days=10)

