import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ROOT = Path(__file__).parent

def factors():
    for path in (ROOT / "factor_ensemble.json", ROOT / "factors" / "factor_ensemble.json"):
        try:
            fs = json.loads(path.read_text()).get("selected_factors", [])
            if 0 < len(fs) <= 10:
                return fs
        except Exception:
            pass
    return []

def pct(p, n):
    return p[-1] / p[-n-1] - 1.0

def signal(fid, p, cross):
    # p ends at the latest completed session; all signals are deliberately lagged.
    p = p[:-1]
    r = p[1:] / p[:-1] - 1.0
    v20 = max(float(np.std(r[-20:])), .008)
    v30 = max(float(np.std(r[-30:])), .008)
    v40 = max(float(np.std(r[-40:])), .008)
    r20, r30, r40 = pct(p, 20), pct(p, 30), pct(p, 40)
    down = max(float(np.std(r[-40:][r[-40:] < 0])) if np.sum(r[-40:] < 0) >= 5 else v40, .008)
    if fid == "volatility_premium_20d": return v20
    if fid == "breadth_persistence_quality_40d": return r40 / v40
    if fid == "dispersion_normalized_momentum_40d": return r20 / v20
    if fid == "miner_1_20350426_volatility_shock_reversal_40d": return -r40 / v40
    if fid == "miner_2_downside_adjusted_momentum_30d": return r30 / down
    if fid == "miner_2_20341123_downside_sharpe_momentum_40d": return r40 / down
    if fid == "miner_1_range_momentum_blend_20d":
        hi, lo = np.max(p[-41:]), np.min(p[-41:])
        location = (p[-1] - lo) / max(hi - lo, 1e-9)
        return .5 * (r20 / v20) + .5 * (0.5 - location) / v20
    return 0.0

def ranks(vals):
    out = {s: .5 for s in UNIVERSE}
    good = sorted((v, s) for s, v in vals.items() if np.isfinite(v))
    for i, (_, s) in enumerate(good): out[s] = (i + 1) / len(good)
    return out

def weights(score):
    x = np.array([max(score[s], 1e-8) for s in UNIVERSE], float)
    x /= x.sum()
    # 3%-14% bounds provide diversification while retaining cross-sectional tilt.
    for _ in range(50):
        old = x.copy(); x = np.clip(x, .03, .14)
        free = (x > .0300001) & (x < .1399999)
        if not free.any(): break
        x[free] *= (1.0 - x[~free].sum()) / x[free].sum()
        if np.max(abs(x-old)) < 1e-10: break
    x = np.clip(x, .03, .14); x /= x.sum()
    return {s: float(x[i]) for i, s in enumerate(UNIVERSE)}

@register_hook
def strategy():
    fs = factors()
    if not fs: return
    prices = {}
    for s in UNIVERSE:
        try:
            d = get_stock_daily_data(symbol=s, days=260)
            p = np.asarray(d.sort_values("date")["close"], float) if d is not None else np.array([])
            if len(p) >= 130 and np.all(np.isfinite(p)) and np.all(p > 0): prices[s] = p
        except Exception: pass
    if len(prices) < 12: return
    cross = {s: pct(p[:-1], 20) for s, p in prices.items()}
    score = {s: .5 for s in UNIVERSE}
    for f in fs:
        raw = {s: signal(str(f["factor_id"]), p, cross) * float(f.get("direction", 1)) for s,p in prices.items()}
        rr = ranks(raw)
        for s in UNIVERSE: score[s] += float(f["weight"]) * (rr[s] - .5)
    # Moderate high-risk overlay: full investment remains, but defensives gain weight.
    try:
        vd = get_index_daily_data(symbol="VIX", days=160)
        v = np.asarray(vd.sort_values("date")["close"], float)
        if len(v) >= 120 and v[-1] > 1.05 * np.median(v[-120:]):
            for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 1.25
            for s in ("BTC", "ETH", "SOX", "NDX", "WTI"): score[s] *= .82
    except Exception: pass
    target = weights(score)
    a = np.array([score[s] for s in UNIVERSE])
    forecast = {s: float(.01 * (score[s] - a.mean()) / max(a.std(), 1e-9)) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in fs], horizon_days=10)

