import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ROOT = Path(__file__).parent

def factors():
    try:
        fs = json.loads((ROOT / "factors" / "factor_ensemble.json").read_text()).get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []

def ret(p, n):
    return float(p[-1] / p[-n-1] - 1.0)

def signal(fid, p):
    # p contains data through the prior completed session; lag one more session.
    p = p[:-1]
    r = p[1:] / p[:-1] - 1.0
    v20 = max(float(np.std(r[-20:])), .008)
    v40 = max(float(np.std(r[-40:])), .008)
    r20, r30, r40 = ret(p, 20), ret(p, 30), ret(p, 40)
    neg = r[-40:][r[-40:] < 0]
    down = max(float(np.std(neg)) if len(neg) >= 5 else v40, .008)
    if fid == "volatility_premium_20d":
        return v20
    if fid == "breadth_persistence_quality_40d":
        return r40 / v40
    if fid == "miner_3_20310515_risk_scaled_relative_deceleration_20d":
        # Prefer steady medium trend and penalize an exhausted short-term surge.
        return (r40 - 0.5 * r20) / v40
    if fid == "miner_2_downside_adjusted_momentum_30d":
        return ret(p, 30) / down
    if fid == "miner_3_20310501_vix_regime_reversal_20d":
        return -r20 / v20
    if fid == "miner_2_20350621_breadth_conditioned_risk_reversal_20d":
        return -0.5 * r20 / v20 - 0.5 * r40 / v40
    if fid == "miner_1_20350426_volatility_shock_reversal_40d":
        return -r40 / v40
    return 0.0

def ranks(vals):
    out = {s: .5 for s in UNIVERSE}
    good = sorted((float(v), s) for s, v in vals.items() if np.isfinite(v))
    if not good: return out
    for i, (_, s) in enumerate(good): out[s] = (i + 1) / len(good)
    return out

def make_weights(score):
    x = np.array([max(float(score[s]), 1e-8) for s in UNIVERSE])
    x /= x.sum()
    # Full investment, diversified 15-asset book; fractional quantities are allowed.
    for _ in range(100):
        fixed = (x < .03) | (x > .14)
        y = np.clip(x, .03, .14)
        free = ~fixed
        if free.any():
            y[free] *= (1.0 - y[fixed].sum()) / y[free].sum()
        if np.max(np.abs(y - x)) < 1e-10: x = y; break
        x = y
    x = np.clip(x, .03, .14); x /= x.sum()
    return {s: float(x[i]) for i, s in enumerate(UNIVERSE)}

@register_hook
def strategy():
    fs = factors()
    if not fs: return
    prices = {}
    for s in UNIVERSE:
        try:
            d = get_stock_daily_data(symbol=s, days=260)
            p = np.asarray(d.sort_values("date")["close"], dtype=float) if d is not None else np.array([])
            if len(p) >= 130 and np.all(np.isfinite(p)) and np.all(p > 0): prices[s] = p
        except Exception:
            pass
    if len(prices) < 12: return
    score = {s: .5 for s in UNIVERSE}
    for f in fs:
        fid = str(f["factor_id"])
        raw = {s: signal(fid, p) * float(f.get("direction", 1)) for s, p in prices.items()}
        rr = ranks(raw)
        w = float(f["weight"])
        for s in UNIVERSE: score[s] += w * (rr[s] - .5)
    # Bullish but medium-high risk: retain full exposure and bias toward defensives if stress rises.
    try:
        vd = get_index_daily_data(symbol="VIX", days=160)
        v = np.asarray(vd.sort_values("date")["close"], dtype=float)
        if len(v) >= 120 and v[-1] > 1.05 * np.median(v[-120:]):
            for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 1.25
            for s in ("BTC", "ETH", "SOX", "NDX", "WTI"): score[s] *= .82
    except Exception:
        pass
    target = make_weights(score)
    a = np.array([score[s] for s in UNIVERSE], dtype=float)
    z = (a - a.mean()) / max(a.std(), 1e-9)
    forecast = {s: float(.01 * z[i]) for i, s in enumerate(UNIVERSE)}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in fs], horizon_days=10)

