import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ROOT = Path(__file__).parent


def load_factors():
    for path in (ROOT / "factor_ensemble.json", ROOT / "factors" / "factor_ensemble.json"):
        try:
            fs = json.loads(path.read_text()).get("selected_factors", [])
            if 0 < len(fs) <= 10:
                return fs
        except Exception:
            pass
    return []


def returns(p):
    return p[1:] / p[:-1] - 1.0


def ret(p, n):
    return float(p[-1] / p[-n-1] - 1.0)


def factor_signal(fid, p):
    # The final row is excluded: decisions only see the last completed session.
    p = p[:-1]
    r = returns(p)
    v20 = max(float(np.std(r[-20:])), 0.008)
    v40 = max(float(np.std(r[-40:])), 0.008)
    neg = r[-40:][r[-40:] < 0]
    downside = max(float(np.std(neg)) if len(neg) >= 5 else v40, 0.008)
    r20, r30, r40 = ret(p, 20), ret(p, 30), ret(p, 40)
    if fid == "volatility_premium_20d":
        return v20
    if fid == "breadth_persistence_quality_40d":
        return r40 / v40
    if fid == "miner_3_20310515_risk_scaled_relative_deceleration_20d":
        return (r40 - 0.5 * r20) / v40
    if fid == "miner_2_downside_adjusted_momentum_30d":
        return r30 / downside
    if fid == "miner_1_trend_persistence_120d":
        v120 = max(float(np.std(r[-120:])), 0.008)
        # Low-turnover contrarian interpretation supplied by the screener.
        return -ret(p, 120) / v120
    if fid == "miner_1_20350426_volatility_shock_reversal_40d":
        return -r40 / v40
    if fid == "miner_3_20310501_vix_regime_reversal_20d":
        return -r20 / v20
    return 0.0


def cross_sectional_ranks(values):
    out = {s: 0.5 for s in UNIVERSE}
    valid = sorted((float(v), s) for s, v in values.items() if np.isfinite(v))
    for i, (_, s) in enumerate(valid):
        out[s] = (i + 1) / len(valid)
    return out


def target_weights(score):
    x = np.array([max(float(score[s]), 1e-8) for s in UNIVERSE])
    x /= x.sum()
    # Diversified full-investment book; no cash sleeve and fractional units permitted.
    for _ in range(20):
        y = np.clip(x, 0.03, 0.14)
        y /= y.sum()
        if np.max(np.abs(y - x)) < 1e-10:
            break
        x = y
    x = np.clip(y, 0.03, 0.14)
    x /= x.sum()
    return {s: float(x[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def strategy():
    fs = load_factors()
    if not fs:
        return
    prices = {}
    for symbol in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=symbol, days=260)
            if df is None:
                continue
            p = np.asarray(df.sort_values("date")["close"], dtype=float)
            if len(p) >= 130 and np.all(np.isfinite(p)) and np.all(p > 0):
                prices[symbol] = p
        except Exception:
            continue
    if len(prices) < 12:
        return

    score = {s: 0.5 for s in UNIVERSE}
    for f in fs:
        fid = str(f["factor_id"])
        raw = {s: factor_signal(fid, p) * float(f.get("direction", 1)) for s, p in prices.items()}
        ranked = cross_sectional_ranks(raw)
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * (ranked[s] - 0.5)

    # Bullish but medium-high risk: keep 100% invested and rotate toward defensives on stress.
    try:
        vix_df = get_index_daily_data(symbol="VIX", days=160)
        vix = np.asarray(vix_df.sort_values("date")["close"], dtype=float)
        if len(vix) >= 120 and vix[-1] > 1.05 * np.median(vix[-120:]):
            for s in ("XAU", "US10Y", "CN10Y"):
                score[s] *= 1.25
            for s in ("BTC", "ETH", "SOX", "NDX", "WTI"):
                score[s] *= 0.82
    except Exception:
        pass

    target = target_weights(score)
    z = (np.array([score[s] for s in UNIVERSE]) - np.mean(list(score.values()))) / max(np.std(list(score.values())), 1e-9)
    forecast = {s: float(0.01 * z[i]) for i, s in enumerate(UNIVERSE)}
    rebalance_to_weights(
        target, forecast_returns=forecast,
        factor_ids=[str(f["factor_id"]) for f in fs], horizon_days=10,
    )

