import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ROOT = Path(__file__).parent


def load_factors():
    for path in (ROOT / "factor_ensemble.json", ROOT / "factors" / "factor_ensemble.json"):
        try:
            fs = json.loads(path.read_text()).get("selected_factors", [])
            if 0 < len(fs) <= 10:
                return fs
        except Exception:
            continue
    return []


def factor_value(fid, p):
    # The last returned row can be the current/incomplete session.
    p = p[:-1]
    r = p[1:] / p[:-1] - 1.0
    def vol(n): return max(float(np.std(r[-n:])), 0.008)
    def ret(n): return float(p[-1] / p[-n-1] - 1.0)
    v20, v40 = vol(20), vol(40)
    neg = r[-40:][r[-40:] < 0]
    down = max(float(np.std(neg)) if len(neg) >= 5 else v40, 0.008)
    r20, r30, r40 = ret(20), ret(30), ret(40)
    if fid == "volatility_premium_20d": return v20
    if fid == "breadth_persistence_quality_40d": return r40 / v40
    if fid == "miner_3_20310515_risk_scaled_relative_deceleration_20d": return (r40 - .5*r20) / v40
    if fid == "miner_2_downside_adjusted_momentum_30d": return r30 / down
    if fid == "miner_1_20350426_volatility_shock_reversal_40d": return -r40 / v40
    if fid == "miner_3_20310501_vix_regime_reversal_20d": return -r20 / v20
    return 0.0


def rank_map(values):
    out = {s: .5 for s in UNIVERSE}
    valid = sorted((float(v), s) for s, v in values.items() if np.isfinite(v))
    for i, (_, s) in enumerate(valid):
        out[s] = (i + 1.0) / len(valid)
    return out


def full_weights(score):
    x = np.array([max(float(score[s]), 1e-8) for s in UNIVERSE])
    x /= x.sum()
    # Diversification is appropriate for a 15-asset, medium-high risk cross-section.
    for _ in range(20):
        y = np.clip(x, .03, .14)
        y /= y.sum()
        if np.max(np.abs(y - x)) < 1e-12: break
        x = y
    y = np.clip(x, .03, .14)
    y /= y.sum()
    return {s: float(y[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def strategy():
    factors = load_factors()
    if not factors: return
    prices = {}
    for s in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=s, days=260)
            p = np.asarray(df.sort_values("date")["close"], dtype=float) if df is not None else np.array([])
            if len(p) >= 130 and np.all(np.isfinite(p)) and np.all(p > 0): prices[s] = p
        except Exception:
            pass
    if len(prices) < 12: return

    score = {s: .5 for s in UNIVERSE}
    for f in factors:
        fid, direction = str(f["factor_id"]), float(f.get("direction", 1))
        raw = {s: direction * factor_value(fid, p) for s, p in prices.items()}
        rr = rank_map(raw)
        for s in UNIVERSE: score[s] += float(f["weight"]) * (rr[s] - .5)

    # Risk overlay uses observation-only VIX solely as a signal; it is never traded.
    try:
        d = get_index_daily_data(symbol="VIX", days=160)
        v = np.asarray(d.sort_values("date")["close"], dtype=float)
        if len(v) >= 120 and v[-1] > 1.05 * np.median(v[-120:]):
            for s in ("XAU", "US10Y", "CN10Y"): score[s] *= 1.25
            for s in ("BTC", "ETH", "SOX", "NDX", "WTI"): score[s] *= .82
    except Exception:
        pass

    target = full_weights(score)
    z = (np.array([score[s] for s in UNIVERSE]) - np.mean(list(score.values()))) / max(np.std(list(score.values())), 1e-9)
    forecast = {s: float(.01 * z[i]) for i, s in enumerate(UNIVERSE)}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in factors], horizon_days=10)

